# ২৬তম অধ্যায়: বন্দনা (শাহ মুহম্মদ সগীর)

**বাংলা সাহিত্য • নবম-দশম শ্রেণি (NCTB ২০২৬ শিক্ষাক্রম)**
*কবিতা বিভাগ — রচয়িতা: শাহ মুহম্মদ সগীর*

---

### ✍️ কবি-পরিচিতি
> কবি-পরিচিতি [শাহ মুহম্মদ সগীর আনুমানিক খিস্টীয় ১৪-১৫ শতকের কবি। মুসলমান কবিদের মধ্যে তিনিই
প্রাচীনতম । তিনি গৌড়ের সুলতান গিয়াসউদ্দীন আজম শাহের রাজত্কালে (১৩৯৩-১৪০৯ খিষ্টাব্দ) ইউসুফ
জোলেখা কাব্য রচনা করেন। কাব্যটি পঞ্চদশ শতকের প্রথম দশকে রচিত হয়েছিল বলে অনুমান
করা হয়। কাব্যের রাজবন্দনায় “মহামতি গ্যেছ' বলে যাঁকে উল্লেখ করা হয়েছে তিনি গিয়াসউদ্দীন
আজম শাহ বলে অনুমিত। শাহ মুহম্মদ সগীরের কাব্যে চট্টগ্রাম অঞ্চলের কতিপয় শব্দের ব্যবহার
লক্ষ করে মুহাম্মদ এনামুল হক তাকে চট্টগ্রামের অধিবাসী বলে বিবেচনা করেছেন। শাহ মুহম্মদ সগীর তাঁর
ইউসুফ জোলেখা কাব্যে দেশি ভাষায় ধর্মীয় উপাখ্যান বর্ণনা করতে চেয়েছিলেন, তবে কাব্যে ধর্মীয়
পটভূমি থাকলেও তা হয়ে উঠেছে মানবিক প্রেমোপাখ্যান |

---

## 📖 মূল পাঠ (কবিতা)

বন্দনা
শাহ মুহম্মদ সগীর



দ্বিতীয়ে প্রণাম করৌ মাও বাপ পাএ।
যান দয়া হত্তে জন্ম হৈল বসুধায় ॥
পিপিড়ার ভয়ে মাও না থুইলা মাটিত।
কোল দিআ বুক দিআ জগতে বিদিত ॥
তান দয়া হন্তে হেল এ ধড় বিশাল ॥
না খাই খাওয়াএ পিতা না পরি পরাএ।
কত দুক্ষে একে একে বছর গোঞ্াএ ॥
পিতাক নেহায় জিউ জীবন যৌবন।
কনে বা সুধিব তান ধারক কাহন ॥
ওস্তাদে প্রণাম করো খিতা হস্তে বাড়।
দোসর-জনম দিলা তিহ সে আন্গার ॥
আন্মা পুরবাসী আছ জথ পৌরজন।
ইষ্ট মিত্র আদি জথ সভাসদগণ ॥
তান সভান পদে মোহার বহুল ভকতি।
সপুটে প্রণাম মোহার মনোরথ গতি
মুহম্মদ সগীর হীন বহৌ পাপ ভার ।
সভানক পদে দোয়া মাগো বার বার ॥

---

### 📚 শব্দার্থ ও টীকা

পুরবাসী- নগরবাসী । বন্দনা- স্তৃতি, প্রশংসা | করৌ- করি। যান- যার । হন্তে- হতে, থেকে । থুইলা-
রাখল । অশক্য- অশক্ত, দুর্বল । আছিলু- ছিলাম । মুই- আমি । ছাবাল- ছাওয়াল, ছেলে, সন্তান। তান-
তাঁর। গোঙাএ- গুজরান করে, অতিবাহিত করে। পিতাক- পিতাকে । নেহায়- গ্লেহে। বিদিত-
জানা । মনোরথ- ইচ্ছা, অভিলাষ । জিউ- আয়ু,জীবিত থাকা । কনে- কখনও । ধারক- ধারের,
খণের। কাহন- ষোলোপণ, টাকা । বাড়- বাড়া, বেশি। দোসর- দ্বিতীয়। মোহার- আমার । সপুটে-
করজোড়ে | সভান- সবার । সভানক- সবার । বসুধায়- পৃথিবীতে । তিহ- তিনিও । আন্দার- আমার ।
বিদিত- জানা । পিঁপিড়ার ভয়ে মাও না থুইলা মাটিত- মায়ের সহ মমতার তুলনা নেই। মায়ের
সদাজাগ্তত কল্যাণদৃষ্টি সন্তানের জীবনপথের পাথেয় স্বরূপ। শিশুকে মা বহু যত্নে লালন-পালন
করেন। পিঁপড়ার ভয়ে মা সন্তানকে মাটিতে রাখেনি- এই কথা উল্লেখ করে কবি মায়ের সেই শ্বেহ
মমতা ও কল্যাণ দৃষ্টিকেই বড় করে তুলেছেন। অশক্য আছিলু মুই দুর্বল ছাবাল- এখানে কবি মানব
শিশুর শৈশবকালীন অসহায় অবস্থার প্রতি আমাদের দৃষ্টি আকর্ষণ করেছেন। মায়ের আদর-যত্ব
ও কৃতজ্ঞতা প্রকাশের উদ্দেশ্যে এই পঙক্তিটি ব্যবহার করেছেন।

---

### 📝 পাঠ-পরিচিতি :

শাহ মুহম্মদ সগীরের ইউসুফ জোলেখা কাব্যের “বন্দনা” পর্ব থেকে গৃহীত এই কবিতাংশ “বন্দনা'
নামে সংকলিত হয়েছে। বন্দনা" পর্ব যথেষ্ট বড়ো, এখানে শুধু গুরুজনদের প্রতি বন্দনার অংশটুকু
স্থান পেয়েছে। কবি তাঁর মূল কাব্যের প্রারস্তে সৃষ্টিকর্তা আল্লাহর প্রশংসা করেছেন। সংকলিত এই
কবিতাংশে জন্মদাতা পিতামাতার ও জ্ঞানদাতা শিক্ষকের প্রতি শ্রদ্ধা নিবেদন করেছেন । পিতামাতা
অশেষ দুঃখকষ্ট স্বীকার করে পরম যত্তরে সন্তানকে বড় করে তোলেন । শিক্ষক জ্ঞানদান করে তাকে
সাফল্য লাভের জন্য সবার কাছে দোয়া কামনা করেছেন। শ্রদ্ধাবোধ ও কৃতজ্ঞতা মনুষ্যত্বের প্রধান ধর্ম।
কবিতাংশে তা-ই প্রকাশিত হয়েছে।

কর্ম-অনুশীলন
১. তোমার জীবন গঠনে পিতামাতার অবদান বিষয়ে একটি অনুচ্ছেদ রচনা করো ।
২. গুরুজনদের প্রতি কীভাবে শ্রদ্ধা-প্রদর্শন করবে তার একটি তালিকা তৈরি করো ।

---

### ✍️ মূল পাঠ্যবইয়ের নমুনা প্রশ্ন
বহুনির্বাচনি প্রশ্ন
১. “বন্দনা' কবিতায় কীসের ভয়ে মা সন্তানকে মাটিতে রাখেননি?
ক. ঠাণ্ডা খ. পিঁপড়া

গ. পোকা ঘ. মশক



২. “না খাই খাওয়াএ পিতা,_-এ চরণে প্রকাশ পেয়েছে _
1. অপত্যন্রেহ
11. সন্তান বাৎসল্য
111. উদারতা
নিচের কোনটি ঠিক?
নিচের উদ্দীপকটি পড়ে ৩ ও ৪ নং প্রশ্নের উত্তর দাও।

অমর্ত্য সেন নোবেল পুরস্কার লাভ করে তার প্রিয় জনুভূমি বাংলাদেশে বেড়াতে আসেন । হাজারো কর্মব্যস্ততার
মধ্যেও তিনি ছুটে যান শৈশবের বিদ্যাপীঠে, শ্রদ্ধাভরে স্মরণ করেন তীর দীক্ষাগ্ডরুদের, যাঁদের কাছে তিনি
হাতেখড়ি নিয়েছিলেন।

৩। উদ্দীপকের অমর্ত্য সেন-এর মাঝে “বন্দনা” কবিতার কবির চেতনার কোন দিকটি ফুটে উঠেছে?

ক, ৩বশ৩বরত
খ. স্বদেশপ্রেম
গ. গুরুভক্তি

ঘ. স্বাজাত্যবোধ

৪। কবির উল্লিখিত চেতনা প্রকাশ পেয়েছে নিচের কোন চরণে?

ক. ইষ্ট মিত্র আদি জথ সভাসদগণ
খ. দোসর জনম দিলা তিহ সে আন্গার
গ. যান দয়া হন্তে জন্ম হৈল বসুধায়
ঘ. কোল দিআ বুক দিআ জগতে বিদিত

---

### ✍️ মূল পাঠ্যবইয়ের সৃজনশীল প্রশ্ন

১। বায়েজিদ বোস্তামির মা এক রাতে পানি খেতে চান। ঘরে পানি না থাকায় তা বাহির থেকে সংগ্রহ করে ফিরে
এসে দেখেন মা ঘুমিয়ে পড়েছেন। পানির পাত্র হাতে বায়েজিদ সারারাত মায়ের শিয়রে দাঁড়িয়ে থাকেন,যাতে
ঘুম থেকে জাগলেই মাকে পানি দিতে পারেন । মা যেন পিপাসায় কষ্ট না পান।

ক. “বন্দনা' কবিতায় পিতার চেয়েও কাকে বেশি শ্রদ্ধা দেখাতে বলা হয়েছে?
গ. উদ্দীপকের বায়েজিদের মাঝে “বন্দনা” কবিতার যে দিক প্রকাশ পেয়েছে তা ব্যাখ্যা করো।
ঘ. “প্রকাশিত দিকটিই “বন্দনা” কবিতার একমাত্র উপজীব্য নয় ”- মন্তব্যটির যথার্থতা যাচাই করো ।

---

### ❓ পাঠভিত্তিক প্রশ্ন ও উত্তর (Comprehension Q&A)

> ❓ **প্রশ্ন: ‘বন্দনা’ কবিতায় কবি পিতামাতার প্রতি কী বার্তা দিয়েছেন?**
> 💡 **উত্তর:** কবি বলেছেন, পিতামাতা হলেন পৃথিবীতে ঈশ্বরের পরম রহমতের প্রতীক। তাঁদের স্নেহ ও লালন-পালনের ঋণ কখনো শোধ করা যায় না, তাই তাঁদের প্রতি আজীবন গভীর শ্রদ্ধা নিবেদন কর্তব্য।

> ❓ **প্রশ্ন: কবি গুরুর মর্যাদা কীভাবে বর্ণনা করেছেন?**
> 💡 **উত্তর:** পিতা সন্তানের শারীরিক জন্ম দেন, কিন্তু শিক্ষক দেন আধ্যাত্মিক ও আত্মিক জ্ঞান; তাই শিক্ষকের আসনও পরম সম্মানের।
