# ২৭তম অধ্যায়: হাম্দ (আলাওল)

**বাংলা সাহিত্য • নবম-দশম শ্রেণি (NCTB ২০২৬ শিক্ষাক্রম)**
*কবিতা বিভাগ — রচয়িতা: আলাওল*

---

### ✍️ কবি-পরিচিতি
> কবি-পরিচিতি : সৈয়দ আলাওল আনুমানিক ১৬০৭ খিষ্টান্দে উ্টগ্রাম জেলার ফতেয়াবাদের অন্তর্গত
জোবরা গ্রামে, মতান্তরে ফরিদপুরের ফতেয়াবাদ পরগনায় জনুগ্রহণ করেন। তাঁর পিতা ছিলেন
ফতেয়াবাদের শাসনকর্তা মজলিশ কুতুবের অমাত্য । জলপথে চট্টগ্রাম যাওয়ার সময় আলাওল ও
তাঁর পিতা পর্তুগিজ জলদস্যুদের দ্বারা আক্রান্ত হন। যুদ্ধে পিতা নিহত হলে আলাওল পর্তুগিজ
জলদস্যুদের হাতে পড়ে আরাকানে নীত হন। সেখানে তিনি আরাকানরাজ সাদ উমাদারের দেহরক্ষী
অশ্বারোহী সেনাদলে চাকরি লাভ করেন। রাজমন্ত্রী মাগন ঠাকুর তাঁর বিদ্যাবুদ্ধি ও প্রতিভার পরিচয়
পেয়ে তাঁকে পৃষ্ঠপোষকতা দান করেন। তিনি আরবি, ফারসি, হিন্দি ও সংস্কৃত ভাষায় সুপপ্তিত ছিলেন।
এছাড়া তিনি রাগসংগীত, যোগ ও ভেষজশাস্ত্ব, সুফিতত্্র ও বৈষ্ঞবসাধনা ইত্যাদি বিষয়ে পারদর্শী
ছিলেন। আলাওলের যেসব গ্রন্থের সন্ধান পাওয়া গেছে সেগুলো হলো : পদ্মাবতী, সয়ফুলমুলক
বদিউজ্জামাল, হগপয়কর, সেকান্দরনামা, তোহফা ইত্যাদি । আলাওলের কাব্য অনুবাদমূলক হলেও
তা মৌলিকতার দাবিদার । আলাওল আনুমানিক ১৬৭৩ খ্রিষ্টাব্দে মৃত্যুবরণ করেন |

