### 📚 শব্দার্থ ও টীকা
হামদ- সাধারণ অর্থ: প্রশংসা, বিশেষ অর্থ : আল্লাহর প্রশংসা । বিছমিল্লা- আল্লাহর নামে শুরু করা,
কোনো কাজ শুরু করার আগে মুসলমানেরা “বিসমিল্লাহ' বলেন। পূর্ণ বাক্যটি হলো : বিসমিল্লাহির
প্রকটিল- প্রকাশ করল। কবিলাস- কৈলাস বা স্বর্গ । ক্ষিতি- মাটি। সপ্ত মহী- সাত স্তর বিশিষ্ট পৃথিবী ।
নর্ক- নরক। সপ্ত ব্রক্মা- সাত স্তর বিশিষ্ট আকাশ । চতুর্দশ ভুবন- পৃথিবীর সাত স্তর এবং আকাশের
সাত স্তর মিলে চতুর্দশ ভুবন। দিবাকর- সূর্য । শশী-চাঁদ। পাঁতিপ্পাতি- প্ক্তিতে পঙ্ক্তিতে ৷ সিপিতে-
ঝিনুকে। ভুগ্য়- ভাগ করে। ভাঁতি- শোভা, ভুগত- ভোগ করতে, দর্শাইতে- দেখাতে ।
---

### 📝 পাঠ-পরিচিতি
হামদ" কবিতাংশটি আলাওলের পদ্মাবতী কাব্য থেকে সং্রহ করা হয়েছে। এটি পদ্মাবতী কাব্যের
প্রারস্তে মহান আল্লাহর প্রশংসাসূচক পর্বের অংশ ।
কবি এই কবিতাংশে বিশ্বসৃষ্টির রহস্য সম্পর্কে আলোকপাত করেছেন। কবি মহান স্রষ্টার প্রতি শ্রদ্ধা
নিবেদন করে তাঁর সৃষ্টির মহিমা বর্ণনা করেছেন। আগুন, বাতাস, পানি ও মাটি এসব উপাদান
সহযোগে আল্লাহ এই বিশাল বিশ্ব সৃষ্টি করেছেন। তারপর জলচরপ্রাণী, কীটপতঙ্গ, বৃক্ষলতা,পশুপাখি
এবং সব শেষে সৃষ্টি করেছেন মানুষ । শ্রষ্টার সৃষ্টির মধ্যে মানুষই শ্রেষ্ঠ । মানুষের উপভোগের জন্য
বিচিত্র উপকরণ প্রদান করা হয়েছে। বিধাতা মানুষকে ভাগ্যের অধীন করে পার্থিব জীবনে সুখী কিংবা

দুঃখী, গুণী কিংবা নিগ্গুণ করে পাঠিয়েছেন । কবিতাংশে ষ্টার খেয়াল ও বিধি অনুযায়ীই যে সৃষ্টিজগত ও
মানবভাগ্য নির্ধারণ হয়েছে তারই আলোকপাত বিধৃত হয়েছে।

কর্ম-অনুশীলন
১. বৈচিত্র্পূর্ণ সৃষ্টিজগতের বিভিন্ন উপাদানের মধ্যকার সম্পর্ক নির্ণয় করো ।
২. মানুষের জীবন বাচাতে ও জীবন সাজাতে ষ্টার দয়া ও করুণার কথা বর্ণনা করো ।

নমুনা প্রন

বহুনির্বাচনি প্রশ্ন

১।  “হামদ্‌* কবিতাংশের আলোকে প্রভু জীবের জন্য প্রথমে কী সৃষ্টি করেছেন?
ক. জ্যোতি খ. ক্ষিতি
গ. শশী ঘ. মহী

২।  “হামদ্‌* কবিতাংশে কবি আলাওল- এর মতে, স্রষ্টার জীব সৃষ্টির কারণ কী?
ক. আনন্দ লাভ খ. সক্ষমতা প্রকাশ
গ. আনুগত্য লাভ ঘ. স্রষ্টার আত্মপ্রকাশ

নিচের উদ্দীপকটি পড়ে ৩ ও ৪ নং প্রশ্নের উত্তর দাও।

তারকা রবি শশী খেলনা তব হে উদাসী

৩। উদ্দীপকটি “হামদ্‌* কবিতাংশের কোন ভাবের সঙ্গে অধিকতর সঙ্গতিপূর্ণ?
ক. শরষ্টার লীলা খ. সৃষ্টিসম্ভার
গ. সৃষ্টিরহস্য ঘ. অষ্টার খেয়াল

৪। সঙ্গতিপূর্ণ দিকটি “হামদ্‌* কবিতার যে চরণে ফুটে উঠেছে_
1. সৃজিলেক সপ্ত মহী এ সপ্ত ব্রন্মাণ্ড 11. সৃজিল সিপিতে মুক্তা রত্বু বহু মূল
111. সৃজিলেক আগুন পবন জল ক্ষিতি
