### ❓ পাঠভিত্তিক প্রশ্ন ও উত্তর (Comprehension Q&A)

> ❓ **প্রশ্ন: আলাওলের ‘হাম্দ’ কবিতার মূল বিষয়বস্তু কী?**
> 💡 **উত্তর:** পরম করুণাময় সর্বশক্তিমান আল্লাহর মহিমা, অসীম ক্ষমতা, বিশ্বজগতের নিখুঁত সৃষ্টি এবং তাঁর অনুগ্রহের প্রতি মানুষের ভক্তিপূর্ণ কৃতজ্ঞতা প্রকাশ।

> ❓ **প্রশ্ন: আল্লাহর নেয়ামতের স্বরূপ কবি কীভাবে ফুটিয়ে তুলেছেন?**
> 💡 **উত্তর:** চন্দ্র, সূর্য, গ্রহ-নক্ষত্র এবং এই সুন্দর ধরণী সবই আল্লাহর কুদরতের নিদর্শন, যা মানুষকে তাঁর করুণার কথা স্মরণ করিয়ে দেয়।
