### ❓ পাঠভিত্তিক প্রশ্ন ও উত্তর (Comprehension Q&A)

> ❓ **প্রশ্ন: ‘বঙ্গবাণী’ কবিতায় আবদুল হাকিম মাতৃভাষার মর্যাদা কীভাবে তুলে ধরেছেন?**
> 💡 **উত্তর:** কবি বলেছেন, মাতৃভাষাই মনের ভাব প্রকাশের সর্বোত্তম মাধ্যম। আল্লাহ সব ভাষাই বোঝেন, তাই মাতৃভাষা বাংলাকে অবহেলা করা চরম হীনম্মন্যতা।

> ❓ **প্রশ্ন: ‘যে সবে বঙ্গেত জন্মি হিংসে বঙ্গবাণী / সে সব কাহার জন্ম নির্ণয় ন জানি’—পঙ্‌ক্তিটির তাৎপর্য কী?**
> 💡 **উত্তর:** বাংলাদেশে জন্মগ্রহণ করে যারা নিজের মাতৃভাষা বাংলাকে ঘৃণা করে, কবি তীব্র ক্ষোভের সাথে তাদের জন্মপরিচয় ও দেশপ্রেম নিয়ে প্রশ্ন তুলেছেন।
