# ২৯তম অধ্যায়: কপোতাক্ষ নদ (মাইকেল মধুসূদন দত্ত)

**বাংলা সাহিত্য • নবম-দশম শ্রেণি (NCTB ২০২৬ শিক্ষাক্রম)**
*কবিতা বিভাগ — রচয়িতা: মাইকেল মধুসূদন দত্ত*

---

### ✍️ কবি-পরিচিতি
> কবি-পরিচিতি : মধুসূদন দত্ত ১৮২৪ খিষ্টাব্দের ২৫শে জানুয়ারি যশোর জেলার সাগরদীড়ি গ্রামে জন্গ্রহণ
করেন। স্কুলজীবনের শেষে তিনি কলকাতার হিন্দু কলেজে ভর্তি হন। এই কলেজে অধ্যয়নকালে ইংরেজি
সাহিত্যের প্রতি তার তীব্র অনুরাগ জন্মে। ১৮৪৩ খিষ্টাব্দে তিনি খিষ্টধর্মে দীক্ষিত হন। তখন তার নামের
প্রথমে যোগ হয় “মাইকেল"। পাশ্চাত্য জীবনযাপনের প্রতি প্রবল আগ্রহ এবংইংরেজি ভাষা ও সাহিত্যের
অভিজ্ঞতায় তার এই ভুল ভেঙেছিল। বাংলা ভাষায় কাব্যরচনার মধ্য দিয়ে তার কবিপ্রতিভার যথার্থ স্কূর্তি
ঘটে। তার অমর কীর্তি “মেঘনাদ-বধ কাব্য'। তার অন্যান্য কাব্য : তিলোতমাসম্ভব কাব্য, বীরাঙ্গনা
কাব্য, ব্জাঙ্গনা কাব্য ও চতুর্শপদী কবিতাবলী। তার নাটক : কৃষ্ণকুমারী, শমির্ঠা, পদ্মাবতী; এবং
প্রহসন : একেই কি বলে সভ্যতা ও বুড় সালিকের ঘাড়ে রৌ। বাংলা কাব্যে অমিত্রাক্ষর ছন্দ এবং সনেট
প্রবর্তন করে তিনি যোগ করেছেন নতুন মাত্রা ৷ ১৮৭৩ খিষ্টান্দের ২৯শে জুন কবি পরলোকগমন করেন |

---

## 📖 মূল পাঠ (কবিতা)

কপোতাক্ষ নদ
মাইকেল মধুসৃদন দত্ত



সতত, হে নদ, তুমি পড় মোর মনে !
সতত তোমার কথা ভাবি এ বিরলে;
সতত (যেমতি লোক নিশার স্বপনে
শোনে মায়া-মন্ত্রধ্বনি) তব কলকলে
জুড়াই এ কান আমি ভ্রান্তির ছলনে !
কিন্ত এ গ্নেহের তৃষ্ণা মিটে কার জলে?
দু্ধ-স্রোতোরূপী তুমি জন্মভূমি-স্তনে ।

আর কি হে হবে দেখা? - যত দিন যাবে,
প্রজারূপে রাজারূপ সাগরেরে দিতে
বারি-রূপ কর তুমি; এ মিনতি, গাবে
বঙ্গজ জনের কানে, সখে, সখা-রীতে
নাম তার, এ প্রবাসে মজি প্রেম-ভাবে
লইছে যে নাম তব বঙ্গের সংগীতে ।



---

### 📚 শব্দার্থ ও টীকা: সতত-সর্বদা ৷ বিরলে-একান্ত নিরিবিলিতে ৷ নিশা-রাত্রি। ভ্রান্তি-ভুল। বারি-রূপ কর-
প্রজা যেমন রাজাকে কর বা রাজস্ব দেয়, তেমনি কপোতাক্ষ নদও সাগরকে জলরূপ কর বা রাজস্ব
দিচ্ছে। চতুর্দশপদী কবিতা- ইংরেজিতে 99161, বাংলায় চতুর্দশপদী কবিতা । চৌদ্দ-চরণ-
সমন্থিত,ভাবসংহত ও সুনিদিষ্ট। চতুর্দশপদী কবিতার প্রথম আট চরণের স্তবককে অষ্টক (0০৫৬০)
এবং পরবর্তী ছয় চরণের স্তবককে ঘটক (99590) বলে । অষ্টকে মূলত ভাবের প্রবর্তনা এবং ঘটক
ভাবের পরিণতি থাকে। চতুর্দশপদী কবিতায় কয়েক প্রকার অন্ত্যমিল প্রচলিত আছে। যেমন, প্রথম আট
চরণ : কখখক কখখক | শেষ ছয় চরণ : ঘঙচ ঘঙ্চ | অথবা প্রথম আট চরণ : কখখগ কখখগ, শেষ
ছয় চরণ : ঘঙঘঙ চচ। “কপোতাক্ষ নদ' একটি চতুর্দশপদী কবিতা । এখানে মিলবিন্যাস :
কখকখ কখখক গঘগ ঘগঘ।

---

### 📝 পাঠ-পরিচিতি : “কপোতাক্ষ নদ" কবিতাটি কবির চতুদর্শপদী কাবিতাবলী থেকে গৃহীত হয়েছে। এই
কবিতায় কবির স্মৃতিকাতরতার আবরণে তার অত্যুজ্্ল দেশপ্রেম প্রকাশিত হয়েছে। কবি যশোর
জেলার কপোতাক্ষ নদের তীরে সাগরদীড়ি গ্রামে জন্মগ্রহণ করেন । শৈশবে মধুসুদন এই নদের তীরে
প্রাকৃতিক পরিবেশে বড় হয়েছেন। যখন তিনি ফ্রান্সে বসবাস করেন, তখন জন্মভূমির শৈশব-কৈশোরের
গ্লেহডোরে তাকে বেঁধেছে, কিছুতেই তিনি তাকে ভুলতে পারেন না। কবির মনে সন্দেহ জাগে, আর
তিনি গ্নেহাদরে যেমন স্মরণ করেন, কপোতাক্ষও যেন একই প্রেমভাবে তাকে সম্েহে স্মরণ করে।
প্রতি অকুণ্ঠ প্রেম যে মানুষের সহজাত প্রবৃত্তি কবিতায় তাই ধরা পড়েছে।

কর্ম-অনুশীলন
১. সনেট বা চতুর্দশপদী কবিতা হিসেবে “কপোতাক্ষ নদের' সার্থকতা নিরূপণ করে আ্যাসাইনমেন্ট তৈরি করো।
২. স্বদেশপ্রেমমূলক দশটি কবিতা সংকলন করে একটি দেয়ালিকা তৈরি করো ।

---

### ✍️ মূল পাঠ্যবইয়ের নমুনা প্রশ্ন
বহুনির্বাচনি প্রশ্ন
১। কপোতাক্ষ নদ' কবিতাটি রচনাকালে কবি কোন দেশে বাস করতেন?
ক. ফ্রা্স খ. ইংল্যান্ড
গ. ইতালি ঘ. যুক্তরাষ্ট্র
২। “লইছে যে তব নাম বঙ্গের সংগীতে ।' এখানে “তব নাম' বলতে বোঝানো হয়েছে
ক. বাঙালি খ. বাংলাদেশ

গ. বাংলা ভাষা ঘ. কপোতাক্ষ নদ

নিচের উদ্দীপকটি পড়ে ৩ ও ৪ নং প্রশ্নের উত্তর দাও।
তুমি মিশেছ মোর দেহের সনে,
তুমি মিলেছ মোর প্রাণে মনে,
তোমার ওই শ্যামবরণ কোমল মূর্তি মর্মে গাথা ||
৩। উদ্দীপকের ভাব “কপোতাক্ষ নদ" কবিতার কোন ভাবের সাথে সাদৃশ্যপূর্ণ?
ক. স্মৃতিকাতরত খ. স্বদেশগ্রীতি
গ. স্বাজাত্যবোধ ঘ. বিহ্বলতা

৪ | উদ্দীপকের উল্লিখিত ভাব নিচের যে চরণে খুঁজে পাওয়া যায় তা হলো-_
1. সতত তোমার কথা ভাবি এ বিরলে;
11. কিন্তু এ শ্রেহের তৃষ্ণা মিটে কার জলে?
11. দুগ্ধ-শ্বোতোরুপী তুমি জন্মভূমি-স্তনে ।

নিচের কোনটি ঠিক?
গ, 1 ও 11 ঘ. 1,711
