### ✍️ মূল পাঠ্যবইয়ের সৃজনশীল প্রশ্ন
ছোটোকালে ছিলাম বাঙালিদের বালুচরে,

কিন্ত আজ মন শুধু ছটফটায় আর শয়নে স্বপনে বাড়ি দিয়ে যায়,
মধুময় স্মৃতিগুলো আমাকে কাদায়, তবু দেশে আর নাহি ফেরা হয়।

সনেটের ষঘটকে কী থাকে?

উদ্দীপকে প্রতিফলিত অনুভূতি “কপোতাক্ষ নদ' কবিতার আলোকে তুলে ধরো ।
“উদ্দীপকে প্রতিফলিত অনুভূতির অন্তরালে যে ভাবটি প্রকাশ পেয়েছে তা-ই
“কপোতাক্ষ নদ" কবিতার মুলভাব” - কথাটির সত্যতা বিচার করো ।

---

### ❓ পাঠভিত্তিক প্রশ্ন ও উত্তর (Comprehension Q&A)

> ❓ **প্রশ্ন: মাইকেল মধুসূদন দত্তের ‘কপোতাক্ষ নদ’ সনেটে স্মৃতিকাতরতা কীভাবে প্রকাশ পেয়েছে?**
> 💡 **উত্তর:** সুদূর ফ্রান্সে বসেও কবি শৈশবের স্নেহের কপোতাক্ষ নদের মিষ্টি জলের কলধ্বনি ভুলতে পারেননি; এই নদী তাঁর কাছে পরম স্নেহের প্রতীক।

> ❓ **প্রশ্ন: কবিতার অষ্টক ও ষটকের ভাবগত রূপান্তর ব্যাখ্যা করো।**
> 💡 **উত্তর:** অষ্টকে শৈশবের নদীর স্মৃতি ও তৃষ্ণার আকুলতা ব্যক্ত হয়েছে, আর ষটকে প্রকাশ পেয়েছে স্বদেশ ও নদের কাছে কবির বিনম্র বিদায় ও ভালোবাসার প্রার্থনা।
