# ৩০তম অধ্যায়: জীবন-সঙ্গীত (হেমচন্দ্র বন্দ্যোপাধ্যায়)

**বাংলা সাহিত্য • নবম-দশম শ্রেণি (NCTB ২০২৬ শিক্ষাক্রম)**
*কবিতা বিভাগ — রচয়িতা: হেমচন্দ্র বন্দ্যোপাধ্যায়*

---

### ✍️ কবি-পরিচিতি
> কবি-পরিচিতি : হেমচন্দ্র বন্দ্যোপাধ্যায় ১৮৩৮ খিষ্টাব্দের ১৭ই এপ্রিল হুগলি জেলার গুলিটা রাজবল্লভহাট
গ্রামে জনুগহণ করেন । কলকাতা সংস্কৃত কলেজের অধ্যক্ষ প্রসন্নকুমার সর্বাধিকারীর আশ্রয়ে তিনি ইংরেজি

শেখেন। পরবর্তীকালে হিন্দু কলেজে সিনিয়র স্কুল পরীক্ষায় উত্তীর্ণ হন। পরে তিনি কলকাতা বিশ্ববিদ্যালয়
থেকে স্াতক ডিগ্রি লাভ করেন। কর্মজীবনে তিনি সরকারি চাকরি, স্কুল-শিক্ষকতা এবং পরিশেষে আইন
ব্যবসায় নিয়োজিত হন। স্বদেশপ্রেমের অনুপ্রেরণায় তিনি বৃত্রসংহার নামক মহাকাব্য রচনা করেন।

এছাড়া তার উল্লেখযোগ্য কাব্য: চিভাতরঙ্গিনী, বীরবাহু, আশাকানন, ছায়াময়ী ইত্যাদি । ২৪শে মে,
১৯০৩ খষ্টাব্দে হেমচন্দ্র বন্দ্যোপাধ্যায় মৃত্যুবরণ করেন |

---

## 📖 মূল পাঠ (কবিতা)

জীবন-সঙ্গীত

হেমচন্দ্র বন্দ্যোপাধ্যায়



বলো না কাতর স্বরে বৃথা জন্ম এ সংসারে
এ জীবন নিশার স্বপন,

দারা পুত্র পরিবার, তুমি কার কে তোমার
বলে জীব করো না বরন্দন;

মানব-জনম সার, এমন পাবে না আর
বাহ্যদৃশ্যে ভুলো না রে মন;

কর যত্ব হবে জয়, জীবাত্সা অনিত্য নয়,
ওহে জীব কর আকিঞ্চন।

করো না সুখের আশ, পরো না দুখের ফাস,

সংসারে সংসারী সাজ, করো নিত্য নিজ কাজ,
ভবের উন্নতি যাতে হয়।

দিন যায় ক্ষণ যায়, সময় কাহারো নয়,
বেগে ধায় নাহি রহে স্থির,
আয়ু যেন শৈবালের নীর ।

সংসার-সমরাঙ্গনে যুদ্ধ কর দৃঢ়পণে,
ভয়ে ভীত হইও না মানব;

কর যুদ্ধ বীর্ষবান, যায় যাবে যাক প্রাণ
মহিমাই জগতে দুর্লভ।
ভবিষ্যতে করো না নির্ভর;
চিন্তা করে হইও না কাতর ।

মহাজ্ঞানী মহাজন, যে পথে করে গমন,

সেই পথ লক্ষ্য করে স্বীয় কীর্তি ধবজা ধরে
আমরাও হব বরণীয়

সমর-সাগর-তীরে, পদাঙ্ক অঙ্কিত করে
আমরাও হব হে অমর;

করো না মানবগণ, বৃথা ক্ষয় এ জীবন,
ংসার-সমরাঙ্গন মাঝো;

সঙ্কল্প করেছ যাহা, সাধন করহ তাহা,
রত হয়ে নিজ নিজ কাজে ।

---

### 📚 শব্দার্থ ও টীকা : কাতর স্বরে- দুর্বল কণ্ঠে, করুণভাবে। দারা - স্ত্রী। বাহ্যদৃশ্যে - বাইরের
জগতের চাকচিক্যময় রূপে বা জিনিসে। জীবাআ - মানুষের আত্মা। আত্মা যদিও অমর, কিন্তু মানুষের
মৃত্যু অনিবার্ষ, কাজেই দেহ ছেড়ে আত্মা একদিন চলে যাবে, চিরকাল দেহকে আঁকড়ে থাকতে
পারবে না। অনিত্য - অস্থায়ী, যা চিরকালের নয়। আকিঞ্চন - চেষ্টা, আকাজ্ষা; আশ -আশা।
ভবের - জগতের, সংসারের। সমরাঙ্গনে - যুদ্ধক্ষেত্রে কেবি মানুষের জীবনকে যুদ্ধক্ষেত্রের সঙ্গে
তুলনা করেছেন)। বীর্ষবান - শক্তিমান। মহিমা - গৌরব প্রাতঃস্মরণীয় - সকাল বেলায় স্মরণ করার
যোগ্য, অর্থাৎ সকলের শ্রদ্ধা ও সম্মানের পাত্র। ধ্বজা - পতাকা, নিশান। বরণীয় - সম্মানের যোগ্য।
সংসারে-সমরাঙ্গনে - যুদ্ধক্ষেত্রে সাহসী সৈনিকের মতো সংসারেও নানা ঘাত-প্রতিঘাতের মোকাবিলা
করে বেঁচে থাকতে হবে। স্বপন _ রাতের স্বপ্নের মতোই মিথ্যা বা অসার। আয়ু যেন শৈবালের নীর -
শেওলার ওপর পানির ফৌটার মতো ক্ষণস্থায়ী । স্বীয় - নিজ, আপন । পদাঙ্ক - কোনো মহৎ ব্যক্তির
কৃতকর্ম বা চরিত্র ৷ যশোদ্ধারে - খ্যাতির দ্বারে ।

---

### 📝 পাঠ-পরিচিতি : জীবন কেবল নিছক স্বপ্ন নয়। কাজেই এ পৃথিবীকে শুধু স্বগ্ন ও মায়ার
জগৎ বলা যায় না। স্ত্রী-পুত্র-কন্যা এবং পরিজনবর্গ কেউ কারও নয়, একথাও ঠিক নয়। মানব-
জন্ম অত্যন্ত মূল্যবান। মিথ্যা সুখের কল্পনা করে দুঃখ বাড়িয়ে লাভ নেই; তা আমাদের জীবনের
উদ্বেশ্যও নয়। সংসারে বাস করতে হলে সংসারের দায়িত্ব যথাযথভাবে পালন করতে হবে ।
কেননা বৈরাগ্যে মুক্তি নেই । আমাদের জীবন যেন শৈবালের শিশিরবিন্দুর মতো ক্ষণস্থায়ী । সুতরাং
মানুষকে এ পৃথিবীতে সাহসী যোদ্ধার মতো সংগ্রাম করে বেঁচে থাকতে হবে । মহাজ্ঞানী ও মহান
ব্যক্তিদের পথ অনুসরণ করে আমাদেরও বরণীয় হতে হবে। কেননা জীবন তো একবারই।
নেতিবাচকতা পরিহারপূর্বক মহামানবের পদচিহ্ন অনুসরণ করে জীবনপাঠের দীক্ষা গ্রহণের কথা
কবিতাটিতে প্রকাশিত হয়েছে । “জীবন -সঙ্গীত' কবিতাটি মার্কিন কবি 17011 ৬/৪05৬/0170
1.0086110৬-র (১৮০৭-১৮৮২) 4& 73110 0111” শীর্ষক ইংরেজি কবিতার ভাবানুবাদ ।

১. তুমি আদর্শ মনে কর এমন একজন মানুষের সংক্ষিপ্ত পরিচয় দাও ।
২. “জীবন-সঙ্গীত' কবিতার আলোকে মানবজীবন বিফল হওয়ার কারণসমূহ ব্যাখ্যা করো ।

