# ৩১তম অধ্যায়: প্রাণ (রবীন্দ্রনাথ ঠাকুর)

**বাংলা সাহিত্য • নবম-দশম শ্রেণি (NCTB ২০২৬ শিক্ষাক্রম)**
*কবিতা বিভাগ — রচয়িতা: রবীন্দ্রনাথ ঠাকুর*

---

## 📖 মূল পাঠ (কবিতা)

প্রাণ
রবীন্দ্রনাথ ঠাকুর

[লেখক -পরিচিতি : রবীন্দ্রনাথ ঠাকুর ২৫শে বৈশাখ, ১২৬৮ বঙ্গাব্দে (৭ই মে, ১৮৬১ খিষ্টাব্দ) কলকাতার
জোড়াসীকোর ঠাকুর পরিবারে জনুগ্রহণ করেন। ভার পিতা মহর্ষি দেবেন্দ্রনাথ ঠাকুর এবং পিতামহ
প্রি দ্বারকানাথ ঠাকুর । বাল্যকালেই তার কবিপ্রতিভার উন্মেষ ঘটে । মাত্র পনেরো বছর বয়সে তার বনফুল
কাব্য প্রকাশিত হয় । ১৯১৩ খিষ্টাব্দে রবীন্দ্রনাথ ইংরেজি 07/9/7017: 9০7 015/7/৫5 সংকলনের জন্য
এশীয়দের মধ্যে সাহিত্যে প্রথম নোবেল পুরস্কার লাভ করেন। বন্তত তার সাধনায় বাংলা ভাষা ও
সাহিত্য সকল শাখায় দ্রুত উন্নতি লাভ করে এবং বিশ্বদরবারে গৌরবের আসনে প্রতিষ্ঠিত হয় । তিনি একাধারে
প্রবন্ধ,গান ইত্যাদি সাহিত্যের সকল শাখাই তার অবদানে সমৃদ্ধ হয়েছে। তার অজস্র রচনার মধ্যে মানসী,
কবিতা, বিসজর্ন, ডাকঘর, রক্তকরবী, গল্পওচ্ছ, বিচিত্র প্রবন্ধ ইত্যাদি বিশেষভাবে উল্লেখযোগ্য । ২২শে শ্রাবণ,
১৩৪৮ বঙ্গাব্দে এই আগস্ট, ১৯৪১ খিষ্টাব্দ) কলকাতায় বিশ্বকবি রবীন্দ্রনাথ ঠাকুর শেষ নিঃশ্বাস ত্যাগ করেন |]

মরিতে চাহি না আমি সুন্দর ভুবনে
এই সূর্যকরে এই পুষ্পিত কাননে
ধরায় প্রাণের খেলা চিরতরঙ্গিত,
মানবের সুখে দুঃখে গাথিয়া সংগীত

তা যদি না পারি, তবে বাচি যত কাল
তোমরা তুলিবে বলে সকাল বিকাল
নব নব সংগীতের কুসুম ফুটাই।

হাসি মুখে নিয়ো ফুল, তার পরে হায়
ফেলে দিয়ো ফুল, যদি সে ফুল শুকায় ॥

শব্দার্থ ও টাকা : সূর্য করে - সূর্যের কিরণে । চিরতরঙ্গিত - সর্বদা কল্লোলিত, বহমান। লতি - লাভ করি।
জীবন্ত হৃদয় মাঝে - রবীন্দ্রনাথ ঠাকুর তার রচনায় মানুষের মাঝে বেঁচে থাকার আকাঙ্া
প্রকাশ করেছেন। আলোচ্য অংশে তার এই আকাঙ্ার ইঙ্গিত পাওয়া যায়। বিরহমিলন ... অশ্রুময়_
মানব জীবনের এই বৈচিত্রের মধ্যে স্থান করে নিতে চেয়েছেন। আর তার সৃষ্টির মধ্যে ফলিয়ে তুলতে
চেয়েছেন যাপিত জীবনের সুখ-দুঃখ, হাসি-কান্নার বিপুল এক আখ্যান। অমর আলয় - অমর সৃষ্টি
অর্থে। নব নব সঙ্গীতের কুসুম ফুটাই - রবীন্দ্রনাথের সৃষ্টির জগৎ বিপুল। মানুষের জীবনের বিচিত্র
অনুভব-অনুভূতি, ভাব-ভাবনা ও কর্মের জগৎকে তিনি তার সৃষ্টির মধ্যে প্রাণময় করে তুলতে চেয়েছেন।
তার সেই সৃষ্টির মধ্য থেকে রূপ-রস-গন্ধ যেন মানুষ অনুভব করতে পারে, তার জন্য তিনি প্রতিনিয়ত
ফুটিয়ে তুলছেন সৃষ্টির কুসুম ।

---

### 📝 পাঠ-পরিচিতি : কবিতাটি রবীন্দ্রনাথ ঠাকুরের কড়ি ও কোমল কাব্যগ্রন্থ থেকে সংকলিত হয়েছে।
এই জগৎ সুন্দর এবং আকর্ষণীয় । মানুষের হাসি-কান্না, মান-অভিমান, আবেগ-ভালোবাসায় পৃথিবী
পরিপূর্ণ । জগতের মায়া ত্যাগ করে অন্য কিছুর আহ্বানে প্রলুব্ধ হয়ে কবি তাই মৃত্যুবরণ করতে
চান না। তিনি অভিলাষ ব্যক্ত করেছেন, মানুষের মনজয়ী রচনা সৃজনের মাধ্যমে সবার কাছে
আদৃত হওয়ার । পৃথিবীর নরনারীর সুখ-দুঃখ-বিরহ যদি ঠিকভাবে তার সৃষ্টিতে ঠাই পায়, তবেই তিনি
অমর হবেন । তা-না হলে তার রচনা শুকনো ফুলের মতোই সবার কাছে অনাদূত হয়ে পড়বে । সৎ
ও শুভকর্ম করে জগতে মানুষের মধ্যে দীর্ঘদিন বেঁচে থাকার জন্য দৃঢ় সংকল্প প্রয়োজন । কবিতাটিতে
এ প্রত্যয়ই প্রতিফলিত হয়েছে । জীবন তো একবারই । জীবনে নেতিবাচকতা পরিহারপূর্বক মহামানবের
পদচিহ্ন অনুসরণ করে জীবনপাঠের দীক্ষা কবিতাটিতে উচ্চকিত হয়েছে।

কর্ম-অনুশীলন
১। প্রতিটি জীব শেষ মুহূর্ত পর্যন্ত বেঁচে থাকতে চায়'_ উদাহরণের সাহায্যে কথাটি বিশ্লেষণ করো ।

২। বিভিন্নক্ষেত্রে মহত্বীর্তি স্থাপনের মাধ্যমে অমরতৃ লাভ করেছেন এমন ৫জন কৃতী সম্পর্কে ২০০
শব্দের মধ্যে ১টি প্রবন্ধ লেখো ।

