### ✍️ মূল পাঠ্যবইয়ের নমুনা প্রশ্ন
বহুনির্বাচনি প্রশ্ন
ক. স্বর্গে খ. পৃথিবীতে
গ. পুষ্পিত কাননে ঘ. মানুষের মাঝে
২। প্রাণ কবিতায় কবি মানব-হৃদয়ে কীভাবে ঠাই পেতে চেয়েছেন?
ক. ভালোবেসে খ. সৃষ্টির মাধ্যমে

গ. ফুল ফুটিয়ে ঘ. সংগীতের সাহায্যে


প্রাণ

নিচের উদ্দীপকটি পড়ে ৩ ও ৪ নং প্রশ্নের উত্তর দাও।
আবার আসিব ফিরে ধানসিঁড়িটির তীরে - এই বাংলা
হয়তো মানুষ নয় - হয়তো বা শঙ্খচিল শালিকের বেশে

৩। উদ্দীপকের ভাব “প্রাণ কবিতার কোন ভাবের সঙ্গে সাদৃশ্যপূর্ণ?
ক. অমরত্ের বাসনা খ. প্রকৃতিচেতনা
গ. স্বদেশচেতনা ঘ. মৃত্যুচেতনা

