1.  মরিতে চাহি না আমি সুন্দর ভুবনে, মানবের মাঝে আমি বাঁচিবারে চাই।
1. মানবের সুখে-দুঃখে গাথিয়া সংগীত যদি গো রচিতে পারি অমর আলয়!
11. হাসি মুখে নিয়ে ফুল, তার পরে হায় ফেলে দিয়ো ফুল, যদি সে ফুল শুকায়।

নিচের কোনটি ঠিক?
গর 11 ও 111 ঘ. 1১11 ও 111

