> ❓ **প্রশ্ন: ‘প্রাণ’ কবিতায় রবীন্দ্রনাথ ঠাকুরের মানবপ্রেম কীভাবে প্রকাশ পেয়েছে?**
> 💡 **উত্তর:** কবি মরতে চান না, বরং এই সুন্দর পৃথিবীর আলো-বাতাস, মানুষ ও প্রকৃতির হাসিকান্নার মাঝে অনন্তকাল বেঁচে থাকতে চান।

