> 💡 **উত্তর:** কবি নিছক বৈরাগ্য বা সন্ন্যাসে বিশ্বাস করেন না; সাধারণ মানুষের সুখ-দুঃখে অংশীদার হয়ে তাদের হৃদয়ে অমরত্ব লাভ করাই কবির পরম কামনা।
