### ❓ পাঠভিত্তিক প্রশ্ন ও উত্তর (Comprehension Q&A)

> ❓ **প্রশ্ন: ‘জুতা-আবিষ্কার’ কবিতায় রবীন্দ্রনাথ ঠাকুর তৎকালীন রাজা ও মন্ত্রীদের কোন দিকটি ব্যঙ্গ করেছেন?**
> 💡 **উত্তর:** রাজা হবুচন্দ্র ও মন্ত্রী গোবুর চাটুকারিতা, অবাস্তব চিন্তা এবং সামান্য সমস্যাকে বিশাল সংকটে রূপ দেওয়ার বোকামিকে কবি তীব্র ব্যঙ্গের সাথে চিত্রিত করেছেন।

> ❓ **প্রশ্ন: সাধারণ মুচির বুদ্ধি কীভাবে রাজসভার পণ্ডিতদের পরাস্ত করেছিল?**
> 💡 **উত্তর:** পণ্ডিতরা পুরো পৃথিবী ধূলিমুক্ত করতে গিয়ে ব্যর্থ হলেও এক বৃদ্ধ মুচি রাজার চরণ চামড়া দিয়ে ঢেকে দিয়েই অনায়াসে জুতো আবিষ্কার করে রাজাকে রক্ষা করেছিল।
