# ৩৩তম অধ্যায়: অন্ধবধূ (যতীন্দ্রমোহন বাগচী)

**বাংলা সাহিত্য • নবম-দশম শ্রেণি (NCTB ২০২৬ শিক্ষাক্রম)**
*কবিতা বিভাগ — রচয়িতা: যতীন্দ্রমোহন বাগচী*

---

### ✍️ কবি-পরিচিতি
> কবি-পরিচিতি : যতীন্ত্রমোহন বাগচীর জন্ম ১৮৭৮ খিষ্টাব্দের ২৭শে নভেম্বর নদীয়া জেলার জামশেদপুর গ্রামে ।
পল্লি-প্রীতি যতীন্দ্রমোহন বাগচীর কবিমানসের একটা প্রধান বৈশিষ্ট্য ৷ নিসর্গ-সৌন্দর্যে চিত্ররূপময়। রচনায়
গ্রামবাংলার শ্যামল স্নিগ্ধ রূপ উন্মোচনে তিনি প্রয়াসী হয়েছেন । গ্রাম-জীবনের অতি সাধারণ বিষয় ও সুখ-দুঃখ
তিনি সহজ-সরল ভাষায় সহৃদয়তার সঙ্গে তাৎপর্যমপ্তিত করে প্রকাশ করেছেন। তার কাব্যগ্রন্থসমুহের মধ্যে
আছে : লেখা, রেখা, অপরাজিতা, নাগকেশর, বন্ধুর দান, জাগরণী, নীহারিকা ও মহাভারতী। ১লা ফেব্রুয়ারি,
১৯৪৮ খিষ্টাব্দে তিনি মৃত্যুবরণ করেন ॥

---

## 📖 মূল পাঠ (কবিতা)

অন্ধবধু
যতীন্দ্রমোহন বাগচী



আস্তে একটু চল না ঠাকুরঝি _
ওমা, এ যে ঝরা-বকুল! নয়?
রাত্তিরে কাল- মধুমদির বাসে
আকাশ-পাতাল- কতই মনে হয়।

জ্যেষ্ঠ আসতে ক-দিন দেরি ভাই -

_ অনেক দেরি? কেমন করে হবে!
কোকিল-ডাকা শুনেছি সেই কবে,
দখিন হাওয়া _ বন্ধ কবে ভাই;
দীঘির ঘাটে নতুন সিঁড়ি জাগে _
শ্যাওলা-পিছল _ এমনি শঙ্কা লাগে,
পা-পিছলিয়ে তলিয়ে যদি যাই!

মন্দ নেহাত হয় না কিন্তু তায় _
অন্ধ চোখের ছন্দ চুকে যায়!

দুঃখ নাইকো সত্যি কথা শোন,
অন্ধ গেলে কী আর হবে বোন?

বাচবি তোরা - দাদা তো তোর আগে?
বাড়ি আসার পথ খুঁজে না পাবে -

দেখবি তখন - প্রবাস কেমন লাগে?

“চোখ গেল ওই চেচিয়ে হলো সারা ।

জন্ম লাগি গিয়েছে যার চোখ!
কাদার সুখ যে বারণ তাহার - ছাই!

কাদতে পেলে বাচত সে যে ভাই,
কতক তবু কমত যে তার শোক।

“চোখ গেল'_ তার ভরসা তবু আছে-
চক্ষৃহীনার কী কথা কার কাছে!

টানিস কেন? কিসের তাড়াতাড়ি
একলা-থাকা- সেই তো গৃহকোণ_

তার চেয়ে এই খ্রিঞ্ধ শীতল জলে

দুটো যেন প্রাণের কথা বলে_
দরদ-ভরা দুখের আলাপন;

ভুলায় খানিক মনের ব্যথা যত!

---

### 📚 শব্দার্থ ও টীকা : ঠাকুরঝি - ননদ, স্বামীর বোন, শ্বশুরকন্যা। মধুমদির বাসে - মধুর গন্ধে মোহময়
সুগন্ধে আচ্ছনন। আকাশ-পাতাল - নানা বিষয়, নানান ভাবনা-অনুভাবনা অর্থে ব্বহৃত। জ্যৈষ্ঠ আসতে
ক-দিন দেরি ভাই .... - একজন দৃষ্টিপ্রতিবন্ধী মানুষের অনুভবের অসাধারণ এক জগৎ আলোচ্য
অংশে ব্যক্ত হয়েছে। প্রকৃতির বিচিত্র রঙের ধারণা ও অনুভবে এই অন্ধবধূ সমৃদ্ধ ৷ সেই জ্ঞান ও অনুভব
থেকে সে জেনে নিতে চায় খতুর বিবর্তন। অন্ধ চোখের ছন্দ চুকে যাক - অন্ধবধূ অনুভবখদ্ধ মানুষ
অর্থাৎ তার অনুভূতি শক্তি প্রখর । আত্মমর্ধাদা বোধেও সে সমৃদ্ধ । কিন্তু সে অন্ধ । এই অন্ধত্ের কষ্ট
সে গভীরভাবে অনুভব করে । দীঘির ঘাটে যখন শেওলা পড়া পিছল সিঁড়ি জাগে, তখন সে পিছল
খেয়ে জলে পড়ে ডুবে মরার আশঙ্কা প্রকাশ করে। সে এও অনুভব করে যে, ডুবে মরলে অন্ধত্রে
অভিশাপ ঘুচত। কিন্তু কবিতাটির চেতনা থেকে মনে হয়, অন্ধবধূ নৈরাশ্যবাদী মানুষ নয়। জীবনের
প্রতি তার গভীর মমত্ববোধ আছে। চোখ গেল - পাখি বিশেষ । এই পাখির ডাক “চোখ গেল+ শব্দের
মতো মনে হয়। কাদার সুখ - মানুষ দুঃখে কাঁদে, শোকে কীদে। কিন্তু কান্নার মধ্য দিয়ে তার
দুঃখ-শোকের লাঘব ঘটে ।

---

### 📝 পাঠ-পরিচিতি : সমাজ দৃষ্টিহীনদের অবজ্ঞা করে। দৃষ্টিহীনেরা নিজেরাও নিজেদের অসহায় ভাবে।
কোকিলের ডাক শুনে নতুন খতুর আগমন অনুমান করা, শ্যাওলায় পা রেখে নতুন সিঁড়ি জেগে
ওঠার কথা বোঝা দৃষ্টিহীন হয়েও সম্ভবপর । তাই দৃষ্টিহীন হলেই নিজেকে অসহায় না ভেবে, শুধুই
ঘরের মধ্যে আবদ্ধ না থেকে আপন অন্তর্ৃষ্টিকে প্রসারিত করা প্রয়োজন । বধূটি চোখে দেখতে পায় না।
কিন্ত অনুভবে সে জগতের রূপ-রস-গন্ধ সম্পর্কে জ্ঞান রাখে । কবিতাটিতে বিশেষ চাহিদাসম্পন্ন মানুষের
প্রতি ভালোবাসা ও সহমর্মিতা সংবেদনশীল ভাষায় প্রকাশিত হয়েছে।



কর্ম-অনুশীলন
১। তোমার জানা কোনো দৃষ্টিহীন মানুষের বিবরণ দাও ।
২। বিশেষ চাহিদাসম্পন্ন মানুষের প্রতি আমাদের আচরণ কেমন হওয়া উচিত বলে তুমি মনে করো

