# ৩৪তম অধ্যায়: ঝরনার গান (সত্যেন্দ্রনাথ দত্ত)

**বাংলা সাহিত্য • নবম-দশম শ্রেণি (NCTB ২০২৬ শিক্ষাক্রম)**
*কবিতা বিভাগ — রচয়িতা: সত্যেন্দ্রনাথ দত্ত*

---

### ✍️ কবি-পরিচিতি
> কবি-পরিচিতি : ১৮৮২ খিষ্টাব্দে কলকাতার কাছাকাছি নিমতা গ্রামে কবি সত্যেন্দ্রনাথ দত্ত জন্মগ্রহণ
করেন। সত্যেন্দ্রনাথ বিএ শ্রেণি পর্যন্ত পড়াশোনা করেন। ছাত্রজীবন থেকেই তিনি কাব্যচর্চা করতেন ।
দর্শন, বিজ্ঞান, ইতিহাস, ভাষা, ধর্ম ইত্যাদি বিচিত্র বিষয়ের তিনি অনুরাগী ছিলেন। সবিতা, সন্িক্ষণ, বেণু
মধ্যে রয়েছে : তীর্ঘরেণ, তীর্ঘ-সলিল, ফুলের ফসল প্রভৃতি । বিবিধ উপনিষদ ও কবির, নানক প্রমুখের
রচনা এবং আরবি, ফার্সি, চীনা, জাপানি, ইংরেজি, ফরাসি ভাষার অনেক উৎকৃষ্ট কবিতা ও গদ্য রচনা
তিনি বাংলায় অনুবাদ করেন। ছন্দ নির্মাণে তিনি অসাধারণ নৈপুণ্যের পরিচয় দিয়েছেন । এজন্য তিনি “ছন্দের
যাদুকর” বলে পরিচিত হন। ১৯২২ খিষ্টাব্দে মাত্র চল্লিশ বছর বয়সে তিনি পরলোকগমন করেন |

---

## 📖 মূল পাঠ (কবিতা)

ঝরনার গান
সত্যেন্দ্রনাথ দত্ত



চপল পায় কেবল ধাই,
বিভোল মোর সকল প্রাণ ।
শিথিল সব শিলার পর
চরণ থুই দোদুল মন,
বঝিমায় পথ, ঘুমায় বন।
বিজন দেশ, কুজন নাই
একলা গাই, একলা ধাই,
ঝুঁকিয়ে ঘাড় ঝুম-পাহাড়
ভয় দ্যাখায়, চোখ পাকায়;
শঙ্কা নাই, সমান যাই,
টগর-ফুল-নৃপুর পায়,
কোন গিরির হিম ললাট
ঘামল মোর উদ্ভবে,
কোন নাচের উৎসবে ।
খেয়াল নাই-নাই রে ভাই
পাই নি তার সংবাদই,
ধাই লীলায়,-খিলখিলাই-


ঝরনার গান

১৮৩

বুলবুলির বোল সাধি।
বন-ঝাউয়ের ঝোপগুলায়
শিং শিলায়-শিলার গায়,
ডালচিনির রং ধরে।
শালিক শুক বুলায় মুখ
থল-বাঝির মখমলে,
জরির জাল আংরাখায়
অঙ্গ মোর ঝলমলে ।
নিয়ে ধাই, শুনতে পাই
কণ্ঠাতেই তৃষ্ত্রা যার
নিক না সেই পাক ছেকে।
সুন্দরের তৃষ্তা যার
আমরা ধাই তার আশেই।
তার খোঁজেই বিরাম নেই
বিলাই তান-তরল শ্লোক,
আমরা চাই মুগ্ধ-চোখ ।
চপল পায় কেবল ধাই
দুল দোলাই মন ভোলাই,
ঝিলমিলাই দিপ্বিদিক।

