### 📚 শব্দার্থ ও টীকা : বিভোল- অচেতন, বিভোর, বিবশ, বিহ্বল। বিজন- নির্জন, জনশূন্য, নিভৃত।
কুজন- পাখির ডাক। ঝুম-পাহাড়- নীরব পাহাড়, নির্জন পাহাড়। হিম- তুষার, বরফ ।
শুক- টিয়ে পাখি । থল- স্থল। ঝাঁঝি- একপ্রকার জলজ গুল্ম, বহুদিন ধরে জমা শেওলা।
মখমল- কোমল ও মিহি কাপড়। আংরাখা- লম্বা ও টিলা পোশাকবিশেষ। “ফটিক জল"_ স্বচ্ছ
জল, নির্মল জল বা ঝরনার জল । চাতক পাখি ডাকলে “ফটিক জল" শব্দের মতো শোনা যায়।

বিলাই- বিতরণ করি, পরিবেশন করি (বিলোনো থেকে) তান- সুর। তরল শ্লোক_ লঘু বা হালকা
চালের কবিতা । চকোর- পাখি বিশেষ কবি-কল্পনা অনুযায়ী এই পাখি চাদের আলো পান করে।
চন্দ্রমা- চাদের আলো। উপল-ঘায়- পাথরের আঘাতে ।

---

### 📝 পাঠ-পরিচিতি: সত্যেন্দ্রনাথ দত্তের “ঝরনার গান' কবিতাটি কবির বিদায় আরতি কাব্য থেকে সংকলন
করা হয়েছে । কবিতাটিতে অদ্ভুত ধ্বনিব্যঞ্জনায় প্রকাশিত হয়েছে অপূর্ব ভাব । চঞ্চল পা পুলকিত গতিময়;
স্তব্ধ পাথরের বুকে আনন্দের পদচিহ্। নির্জন দুপুরে পাখির ডাকও শোনা যায় না। পাহাড় যেন
দৈত্যের মতো ঘাড় ঘুরিয়ে ভয় দেখায়! এত কিছুর মধ্যেও ঝরনার চঞ্চল ও আনন্দময় পদধ্বনিতে
পর্বত থেকে নেমে আসে সাদা জলরাশির ধারা । চমৎকার এর ধ্বনিমাধূর্ধ ও বর্ণবৈভব। এই
জলধারার যে সৌন্দর্য এবং অমিয় স্বাদ তা তুলনারহিত | গিরি থেকে পতিত এই অন্বুরাশি পাথরের
বুকে আঘাত হেনে চতুর্দিকে ছড়িয়ে পড়ে যে অপূর্ব সৌন্দর্যের সৃষ্টি করে তা সত্যি মনোহর ।

কর্ম-অনুশীলন

১। কবিতাটিতে প্রকৃতির যেসব উপাদান ও প্রাণীর নাম বলা হয়েছে, তার একটি তালিকা করো ।

