### ✍️ মূল পাঠ্যবইয়ের সৃজনশীল প্রশ্ন

নিসর্গকে হাতের মুঠোয় পুরে দেয়ার তাগিদ থেকে পলাশ সাহেব গড়ে তোলেন এক রমণীয় উদ্যান।
বিস্তীর্ণ খোলা মাঠকে সুপরিকল্পিতভাবে তিনি গড়ে তোলেন। পুকুর, দীঘি, হাস, গাছপালা, ফুল, পাখির
বিচিত্র সমারোহ সৌন্দর্য-পিপাসু মানুষমাত্রকেই আকৃষ্ট করে। অনিন্দ্য সুন্দর এই প্রকৃতিকে
শিল্পী তিলোত্তমা করে সাজিয়েছেন শুধুই নিজের খেয়ালে । ব্যক্তিবিশেষ বা কোনো গোষ্ঠীকে আনন্দ
দান নয়, সৌন্দর্যই মুখ্য। বৈরী প্রকৃতি, সামাজিক প্রতিবন্ধকতা উপেক্ষা করে তিনি
এ কাজে অগ্রসর হয়েছেন। সৃষ্টির আনন্দই তাকে এগিয়ে নিয়েছে এতটা পথ ।

“শিথিল সব শিলার পর" বলতে কবি কী বোঝাতে চেয়েছেন?

উদ্দীপকের সাথে “ঝরনার গান' কবিতার সাদৃশ্যপূর্ণ দিকটি ব্যাখ্যা করো।
ঘ. উদ্দীপকটি “ঝরনার গান” কবিতার মূল বক্তব্যকে কতটুকু ধারণ করে? যুক্তিসহ ব্যাখ্যা করো ।

---

### ❓ পাঠভিত্তিক প্রশ্ন ও উত্তর (Comprehension Q&A)

> ❓ **প্রশ্ন: সত্যেন্দ্রনাথ দত্তের ‘ঝরনার গান’ কবিতার ছন্দবৈশিষ্ট্য কী?**
> 💡 **উত্তর:** কবিতাটি দ্রুতগামী, নৃত্যচঞ্চল ও ধ্বনিমাধুর্যে ভরপুর এক অপূর্ব ছন্দোময় সৃষ্টি, যা পাহাড়ি ঝরনার অবিরাম ছুটে চলার ছন্দকে জীবন্ত করে তোলে।

> ❓ **প্রশ্ন: ঝরনার অবিরাম গতি মানুষের মনে কোন প্রেরণা জাগায়?**
> 💡 **উত্তর:** সকল বাধা-বিপত্তি ও জড়তা পেরিয়ে জীবনের চঞ্চলতাকে বজায় রেখে সতত সামনে এগিয়ে চলার প্রেরণা জোগায়।
