### ✍️ মূল পাঠ্যবইয়ের সৃজনশীল প্রশ্ন

বাবার সঙ্গে ঢাকায় বেড়াতে এসে ছিনতাইকারীর কবলে পড়ে উৎপল ও তার বাবা। একপর্যায়ে
ছিনতাইকারীরা উৎপলকে আঘাত করতে এলে বাবা তাকে সরিয়ে দিয়ে নিজে ছিনতাইকারীর ছুরিতে রক্তাক্ত
হন। হাসপাতালে ডাক্তার সাহেব যখন উতৎ্পলকে জানান যে, এই মুহূর্তে রক্ত না হলে রোগী বাচানো যাবে না।
সঙ্গে সঙ্গে উৎপল তার শরীর থেকে প্রয়োজনীয় রক্ত দিয়ে বাবাকে আশঙ্কামুক্ত করেন ।

ক. “জীবন বিনিময়” কবিতায় কোনটিকে “সবচেয়ে শ্রেষ্ঠ ধন" বলা হয়েছে?
গ. উৎপলকে সরিয়ে দেয়ার মধ্য দিয়ে উদ্দীপকের পিতার মাঝে “জীবন বিনিময়' কবিতার বাদশা বাবরের যে
পরিচয় মেলে তা ব্যাখ্যা করো।

ঘ. “ভাবগত এঁক্য থাকলেও উদ্দীপকটি “জীবন বিনিময়” কবিতার ঘটনাপ্রবাহের সমার্থক নয়” - মন্তব্যটি বিশ্লেষণ
করো।

---

### ❓ পাঠভিত্তিক প্রশ্ন ও উত্তর (Comprehension Q&A)

> ❓ **প্রশ্ন: গোলাম মোস্তফার ‘জীবন বিনিময়’ কবিতায় বাবরের পিতৃস্নেহের কোন দিকটি বর্ণিত হয়েছে?**
> 💡 **উত্তর:** সম্রাট বাবর অসুস্থ পুত্র হুমায়ুনের জীবন বাঁচাতে নিজের জীবন আল্লাহর দরবারে উৎসর্গ করেছিলেন; ত্যাগ ও নিঃস্বার্থ ভালোবাসার এক অনন্য দৃষ্টান্ত।

> ❓ **প্রশ্ন: কবিতাটির নৈতিক শিক্ষা কী?**
> 💡 **উত্তর:** পিতামাতার নিঃস্বার্থ স্নেহ ও আত্মত্যাগের মহিমা কোনো পার্থিব ধনদৌলত দিয়ে পরিমাপ করা যায় না।
