# ৩৭তম অধ্যায়: মানুষ (কাজী নজরুল ইসলাম)

**বাংলা সাহিত্য • নবম-দশম শ্রেণি (NCTB ২০২৬ শিক্ষাক্রম)**
*কবিতা বিভাগ — রচয়িতা: কাজী নজরুল ইসলাম*

---

## 📖 মূল পাঠ (কবিতা)

মানুষ
কাজী নজরুল ইসলাম

[লেখক-পরিচিতি : কাজী নজরুল ইসলাম ১১ই জ্যেষ্ঠ, ১৩০৬ বঙ্গাব্দে ২৪শে মে, ১৮৯৯ খিষ্টাব্দ) ভারতের
পশ্চিমবঙ্গের বর্ধমান জেলার আসানসোল মহকুমার চুরুলিয়া গ্রামে জন্গ্রহণ করেন। ছেলেবেলায় তিনি লেটো
গানের দলে যোগ দেন। পরে বর্ধমান ও ময়মনসিংহের ত্রিশাল থানার দরিরামপুর হাই স্কুলে লেখাপড়া করেন।
১৯১৭ খিষ্টাব্দে তিনি সেনাবাহিনীর বাঙালি পল্টনে যোগ দিয়ে করাচি যান। সেখানেই তার সাহিত্য-জীবনের
সূচনা ঘটে। তার লেখায় তিনি সামাজিক অবিচার ও পরাধীনতার বিরুদ্ধে সোচ্চার হয়েছেন। এজন্য তাকে
“বিদ্রোহী কবি” বলা হয়। বাংলা সাহিত্য জগতে তার আবির্ভাব এক নতুন দিগন্তের উন্মোচন করে । কবিতা,
তিনি গজল, খেয়াল ও রাগপ্রধান গান রচনা করে খ্যাতি অর্জন করেন । আরবি-ফারসি শব্দের সার্থক ব্যবহার
হারিয়ে ফেলেন। বাংলাদেশ প্রতিষ্ঠার পর অসুস্থ কবিকে ঢাকায় আনা হয় এবং পরে তীকে বাংলাদেশের
নাগরিকত্‌ প্রদান করা হয়। তাকে স্বাধীন বাংলাদেশের জাতীয় কবির মর্যাদায় ভূষিত করা হয়। তার রচিত
কাব্যগুলোর মধ্যে অহিবীণা, বিষের বাঁশি, ছায়ানট, পলয়শিখা, চক্রবাক, সিন্ধুৃহিন্দোল বিশেষভাবে উল্লেখযোগ্য ।
ব্যথার দান, রিক্তের বেদন, শিউলিমালা, মৃত্যক্ষধা, কৃহেলিকা ইত্যাদি তার রচিত গল্প ও উপন্যাস । যুগবাণী,
দুদিনের যাত্রী ও রাজবন্দীর জবানবন্দী তার উল্লেখযোগ্য প্রবন্ধগ্রন্থ। ২৯শে আগস্ট, ১৯৭৬ খিষ্টাব্দে কবি ঢাকার
পি.জি. হাসপাতালে (বর্তমান নাম বাংলাদেশ মেডিক্যাল বিশ্ববিদ্যালয়) শেষ নিঃশ্বাস ত্যাগ করেন । ঢাকা
বিশ্ববিদ্যালয়ে মসজিদ-সংলগ্ন প্রাঙ্গণে তাকে পরিপূর্ণ রাষ্ট্রীয় মর্যাদায় সমাহিত করা হয় |]

