### ✍️ মূল পাঠ্যবইয়ের সৃজনশীল প্রশ্ন
বন্যায় আক্রান্ত হয়। কিন্ত বানভাসি মানুষ একদিনও চেয়ারম্যান সাহেবের দেখা পেলেন না। কারণ
বাহিনী চেয়ারম্যানের বাগানবাড়ি তল্লাশি করে ত্রাণের প্রচুর টিন ও খাদ্যসামন্্রী উদ্ধার করে।
ক. “উমর ফারুক' কবিতা কোন কাব্য থেকে সংকলিত হয়েছে?
গ. চেয়ারম্যান আব্বাস আলী যেদিক থেকে হজরত উমরের সঙ্গে বৈসাদৃশ্যপূর্ণ তা ব্যাখ্যা করো।
ঘ. আব্বাস আলী চেয়ারম্যানকে উমরের মতো আদর্শ মানুষ হতে হলে কী কী করতে হবে “উমর

