# ৩৯তম অধ্যায়: সেইদিন এই মাঠ (জীবনানন্দ দাশ)

**বাংলা সাহিত্য • নবম-দশম শ্রেণি (NCTB ২০২৬ শিক্ষাক্রম)**
*কবিতা বিভাগ — রচয়িতা: জীবনানন্দ দাশ*

---

### ✍️ কবি-পরিচিতি
> কবি-পরিচিতি : জীবনানন্দ দাশ ১৮৯৯ খিষ্টাব্দে বরিশাল শহরে জন্গ্রহণ করেন । তার পিতার নাম সত্যানন্দ
দাশ, মাতা কুসুমকুমারী দাশ। কুসুমকুমারী দাশও ছিলেন একজন স্বভাবকবি। জীবনানন্দ দাশ বরিশাল
ব্রজমোহন স্কুল, ব্রজমোহন কলেজ ও কলকাতার প্রেসিডেন্সি কলেজে শিক্ষালাভ করেন । কলকাতা
বিশ্ববিদ্যালয় থেকে ইংরেজি সাহিত্যে এমএ ডিগ্রি লাভের পর তিনি অধ্যাপনা শুরু করেন এবং
সুদীর্ঘকাল তিনি অধ্যাপনার কাজে নিযুক্ত ছিলেন । জীবনানন্দ দাশ প্রধানত আধুনিক জীবনচেতনার কবি
হিসেবে পরিচিত । বাংলার প্রকৃতির রূপবৈচিত্র্ে কবি নিমগ্নঁচিত্ত। কবির দৃষ্টিতে বাংলাদেশ এক অনন্য রূপসী ।
এ দেশের গাছপালা, লতাগুল্া, ফুল-পাখি তার আজন্ম প্রিয়। তার রচিত গ্রন্থ : ঝরা পালক, ধুসর পাঙুলিপি,
বনলতা সেন, কবিতার কথা, রূপসী বাংলা, মাল্যবান ইত্যাদি । ১৯৫৪ খিষ্টাব্দের ১৪ই অক্টোবর জীবনানন্দ
দাশ কলকাতায় এক ট্রাম-দুর্ঘটনায় আহত হন এবং ২২শে অক্টোবর মৃত্যুবরণ করেন |

---

## 📖 মূল পাঠ (কবিতা)

সেইদিন এই মাঠ
জীবনানন্দ দাশ



সেই দিন এই মাঠ স্তরূ হবে নাকো জানি-

এই নদী নক্ষত্রের তলে

সেদিনো দেখিবে স্বপ্ন _

সোনার স্বপ্নের সাধ পৃথিবীতে কবে আর ঝরে!
আমি চলে যাব বলে

সোনার স্বগ্নের সাধ পৃথিবীতে কবে আর ঝরে!
চারিদিকে শান্ত বাতি _ ভিজে গন্ধ _ মৃদু কলরব;
খেয়ানৌকোগুলো এসে লেগেছে চরের খুব কাছে;
এশিরিয়া ধুলো আজ -_ বেবিলন ছাই হয়ে আছে।

---

### 📚 শব্দার্থ ও টীকা : সেইদিন এই মাঠ ... কৰে আর ঝরে _ জীবনানন্দ দাশ প্রকৃতির কবি। প্রকৃতির
রহস্যময় সৌন্দর্য তার কবিতার মৌলিক প্রেরণা। তিনি জানেন বিচিত্র বিবর্তনের মধ্যেও প্রকৃতি
তার রুপ-রস-গন্ধ কখনই হারিয়ে ফেলবে না। তিনি যখন থাকবেন না তখনও প্রকৃতি তার অফুরন্ত
এশ্বর্ষ নিয়ে মানুষের স্বগ্র-সাধ ও কল্পনাকে তৃপ্ত করে যাবে । আলোচ্য অংশে কবি প্রকৃতির এই
মাহাত্র্যকে গভীর তৃত্তি ও মমত্বের সঙ্গে উপস্থাপন করেছেন। আমি চলে যাব বলে .. . লক্ষ্মীটির
তরে _ পৃথিবীতে কেউই চিরস্থায়ী নয় প্রত্যেক মানুষকেই এক সময় চলে যেতে হয়। কিন্ত
শিশিরের জলে চালতা ফুল ভিজে যে রহস্যময় সৌন্দর্য সৃষ্টি হয় যুগ-যুগান্তে তার কোনো শেষ
নেই । আর সেই শিশিরের জলে ভেজা চালতা ফুলের গন্ধের ঢেউ প্রবাহিত হতে থাকবে অনন্তকালব্যাপী ।
কবির এই বোধের মধ্যে প্রকৃতির এক শাশ্বতরূপ মূর্ত হয়ে উঠেছে, যেখানে লক্ষমীপেচাটির মমত্রে
অনুভাবনাও ধরা দিয়েছে অসাধারণ এক তাৎপর্যে। এশিরিয়া ধুলো আজ ... - মানুষের গড়া পৃথিবীর
অনেক সভ্যতা বিলীন হয়ে গেছে। এশিরিয় ও ব্যাবিলনীয় সভ্যতা এখন ধ্বংসন্তুপ ছাড়া কিছু নয়।



কিন্ত প্রকৃতি তার আপন রুপ-রস-গন্ধ নিয়ে চিরকাল প্রাণময় থাকে । প্রকৃতির মধ্যে বিচিত্র গন্ধের
আস্বাদ মৃদুমন্দ কোলাহলের আনন্দ, তার অন্তর্গত অফুরন্ত সৌন্দর্য কখনই শেষ হয় না। কবিতাটিতে
জীবনানন্দ দাশ প্রকৃতির এই চিরকালীন সৌন্দর্যকে বিস্ময়কর নিপুণতায় উপস্থাপন করেছেন।

---

### 📝 পাঠ-পরিচিতি : “সেইদিন এই মাঠ' কবিতাটি জীবনানন্দ দাশের রূপসী বাংলা কাব্য থেকে সংকলিত
হয়েছে। সভ্যতা একদিকে যেমন ক্ষয়িষু অন্যদিকে চলে তার বিনির্মাণ। মরণশীল ব্যক্তিমানুষ
মৃত্যুর কোলে ঢলে পড়ে, কিন্ত প্রকৃতিতে থাকে চিরকালের ব্যস্ততা । মাঠে থাকে চঞ্চলতা, চালতাফুলে
পড়ে শীতের শিশির, লক্ষ্মীপেচকের কণ্ঠে ধ্বনিত হয় মঙ্গলবার্তা, খেয়া নৌকা চলে নদীনালাতে-অর্থাৎ
কোথাও থাকে না সেই মৃত্যুর রেশ। ফলে মৃত্যুতেই সব শেষ নয়, পৃথিবীর বহমানতা মানুষের
সাধারণ মৃত্যু রহিত করতে পারে না। প্রকৃতপক্ষে মানুষের মৃত্যু আছে কিন্তু এ জগতে সৌন্দর্ষের মৃত্যু
নেই, মানুষের স্বপ্নেরও মরণ নেই। গভীর জীবনতৃষ্তা নিয়ে এই সত্যই কবিতাটিতে অনুভূত হয়েছে।

কর্ম-অনুশীলন

১। খেয়া নৌকায় পারাপারের বিবরণ দাও ।

---

### ✍️ মূল পাঠ্যবইয়ের নমুনা প্রশ্ন

বহুনির্বাচনি প্রশ্ন

১। “সেইদিন এই মাঠ" কবিতায় বর্ণিত ফুলের নাম কী?
ক. গোলাপ খ. শিউলি
গ. চালতা ঘ. কদম

২। “আমি চলে যাব*-কবি কোথায় চলে যাওয়ার কথা বলেছেন?
ক. গ্রামে খ. শহরে
গ. পরপারে ঘ. বিদেশে
নিচের উদ্দীপকটি পড়ে ৩ নং প্রশ্নের উত্তর দাও।
যখন পড়বে না মোর পায়ের চিহ্ন এই বাটে
তখন আমায় নাই বা তুমি ডাকলে
নাই বা মনে রাখলে ।

৩। উদ্দীপকে “সেইদিন এই মাঠ” কবিতার কোন দিকটি প্রকাশ পেয়েছে?

ক. সৌন্দর্য খ. এতিহ্য
গ. এম্বর্য ঘ. আনন্দ

---

### ✍️ মূল পাঠ্যবইয়ের সৃজনশীল প্রশ্ন

বিভূতিভূষণ বন্দ্যোপাধ্যায় তার কথাসাহিত্যে প্রকৃতিকে একটি জীবন্ত চরিত্র হিসেবে সৃষ্টি
করেছেন। বিশেষ করে “পথের পাঁচালী” ও “আরণ্যক' উপন্যাসে প্রকৃতি চিরকালের নবীনরূপে
আবির্ভূত হয়েছে। অপু, দুর্গা এবং আরও অনেকে সেই চিরন্তন প্রকৃতির সন্তান। এরা যায়-
আসে-_থাকে না। কিন্তু প্রকৃতি চিরকালই নানা রূপ-রস-গন্ধ-বর্ণে বিরাজমান থাকে ।

কী ছাই হয়ে গেছে?
উদ্দীপকের প্রকৃতি জানার সঙ্গে সেইদিন এই মাঠ' কবিতার সাদৃশ্যপূর্ণ দিক ব্যাখ্যা করো।
ঘ. কবিতায় উল্লিখিত সভ্যতার বিবর্তনের সঙ্গে প্রকৃতির সম্পর্ক উদ্দীপকের আলোকে বিশ্লেষণ করো ।

---

### ❓ পাঠভিত্তিক প্রশ্ন ও উত্তর (Comprehension Q&A)

> ❓ **প্রশ্ন: জীবনানন্দ দাশের ‘সেইদিন এই মাঠ’ কবিতায় প্রকৃতির শাশ্বত রূপ কীভাবে চিত্রিত হয়েছে?**
> 💡 **উত্তর:** মানুষ ও সভ্যতার নশ্বর পতন ঘটলেও প্রকৃতি তার নিজস্ব রূপ, গন্ধ ও স্নিগ্ধতা নিয়ে অনন্তকাল চিরসবুজ ও অবিনশ্বর হয়ে বেঁচে থাকে।

> ❓ **প্রশ্ন: ‘পৃথিবীর এইসব গল্প বেঁচে রবে চিরকাল’—পঙ্‌ক্তির গভীর তাৎপর্য কী?**
> 💡 **উত্তর:** ব্যক্তি মানুষের মৃত্যু হলেও প্রকৃতির ভালোবাসা, রূপ এবং মানবজীবনের শাশ্বত অনুভূতিগুলো যুগ যুগ ধরে প্রবাহিত হতে থাকবে।
