# ৪০তম অধ্যায়: যাব আমি তোমার দেশে (জসীমউদ্দীন)

**বাংলা সাহিত্য • নবম-দশম শ্রেণি (NCTB ২০২৬ শিক্ষাক্রম)**
*কবিতা বিভাগ — রচয়িতা: জসীমউদ্দীন*

---

### ✍️ কবি-পরিচিতি
> কবি-পরিচিতি : জসীমউদ্দীন ১৯০৩ খিিষ্টাব্দে ফরিদপুর জেলার তা্ুলখানা গ্রামে জনুগ্রহণ করেন ।
কবি তার কবিতায় বাংলাদেশের পন্লিপ্রকৃতি ও মানুষের সহজ স্বাভাবিক রূপটি তুলে ধরেছেন ।
পলির মাটি ও মানুষের জীবনচিত্র তার কবিতায় নতুন মাত্রা পেয়েছে । পল্লির মানুষের আশা-স্বগ্ন-
আনন্দ-বেদনা ও বিরহ-মিলনের এমন আবেগ-মধুর চিত্র আর কোনো কবির কাব্যে খুঁজে পাওয়া
ভার । এ কারণে তিনি “পল্লিকবি' নামে খ্যাত । কর্মজীবনের শুরুতে তিনি কিছুকাল ঢাকা বিশ্ববিদ্যালয়ে
অধ্যাপনা করেন | পরে সরকারি তথ্য ও প্রচার বিভাগে উচ্চপদে যোগদান করেন । ছাত্রজীবনেই
বাংলা সংকলনের অন্তর্ভূক্ত হয় ৷ জসীমউদ্দীনের উল্লেখযোগ্য কাব্যের মধ্যে রয়েছে নক্রী-
কীথার মাঠ, সোজনবাদিয়ার ঘাট, রাখালী, বালুচর, হাসু, এক পয়সার বাশি, মাটির কানা ইত্যাদি ।
বিশ্বভারতী বিশ্ববিদ্যালয় তাকে সম্মানসূচক ডি.লিট. ডিগ্রি প্রদান করে । এছাড়া সাহিত্য-সাধনার
স্বীকৃতিস্বরূপ তিনি একুশে পদক লাভ করেন। ১৯৭৬ খিষ্টাব্দের ১৩ই মার্চ কবি ঢাকায়

মৃত্যুবরণ করেন |

