### 📚 শব্দার্থ ও টীকা : পল্লি-দুলাল- পল্লি মায়ের আদরের ছেলে । পল্লির অকৃত্রিম প্রাকৃতিক পরিবেশে যে ছেলে
হয়েছে, কবি তাকে পন্লি দুলাল বলে সম্বোধন করেছেন। শীষে- শীর্ষে, মাথার উপরে । বেতসবন-
বেতবন। দীঘল- দীর্ঘ। পন্থ- পথ। দস্যি- দুষ্ট, দুরত্ত । ধল-দীঘি- মস্ত বড় দীঘি। শাখা- গাছের ডাল।
উত্তরীয়- চাদর, গায়ের কাপড় । বুড়াতে- ভরতে । কুন্তল- চুল। বাসে-গন্ধে। ফুলের বাসে- ফুলের সুগন্ধে।
কুহেলী- কুয়াশা । অন্বেষণ- অনুসন্ধান করা, খোজ করা ।

---

### 📝 পাঠ-পরিচিতি :
“যাব আমি তোমার দেশ” কবিতাটি কবি জসীমউদ্দীনের ধানক্ষেত কাব্য থেকে সংকলিত । এই কবিতায়
কৰি আদরের পল্লি-দুলালের দেশে অর্থাৎ পল্লিগ্রামে যেতে চেয়েছেন।

সেখানে বেত-কেয়ার বনে ডাহুক ডাকে । সেখানে ধান-কাউনের ক্ষেতের ভেতর দিয়ে সরু সুতার মত দীর্ঘ
বাকা পথ গেছে। সেই পথে গায়ের মেয়ে কদম কলি ছড়িয়ে হেটে চলে । কবি সেই পথে যাবেন পল্লি-
দুলালের দেশে । তারপর পাড়ার দস্যি ছেলেদের সাথে খেলা করবেন । ধল দীঘিতে সাতার কেটে রক্ত কমল
তুলে আনবেন। মাটিতে পা ফেলে তিনি হাটবেন। পাখির সাথে ডাকবেন । অজানা ফুলের রূপ দেখে মুগ্ধ
হবেন।

পল্লি-দুলালের কাধে হাত রেখে উদাস বেশে তিনি ঘুরে বেড়াবেন। গাছের শাখা দুলিয়ে হাজার রঙের ফুল
তুলবেন। যে ঘাটে পল্িবালারা কলসী ভরে পানি নেয়, সেই ঘাটের পাশে রেখে আসবেন ফুলের মালা ।
তারপর সন্ধ্যা নামবে । চারদিকে আধার আসবে ঘনিয়ে । নিরালা নিঝুম অন্ধকারে কবি পল্লি-দুলালের সাথে
পল্লি মায়ের অপরূপ সৌন্দর্য অন্বেষণ করবেন।

কর্ম-অনুশীলন
১। তোমার দেখা একটি গ্রামের জীবন ও প্রকৃতির ১০টি বৈশিষ্ট্য লেখো ।
