### ✍️ মূল পাঠ্যবইয়ের সৃজনশীল প্রশ্ন

বাড়িতে যাবে । তারা কখনো গ্রাম দেখেনি । বইয়ের পাতায় আর টেলিভিশনে দেখেছে বহুবার, ভালোও
লেগেছে কিন্ত সশরীরে যাওয়া হয়নি কখনো । তাই এ সুযোগ তারা কিছুতেই হাতছাড়া করবে না। তাদের
ভালোলাগা আরো শতগুণ বেড়ে গেছে শাহেদ যখন নিজ গ্রামের বন-বনানী, ফুল, পাখি, দীঘি, শাপলা,
মেঠো পথ, ছেলেমেয়েদের দুরন্তপনা ইত্যাদির নয়নাভিরাম বর্ণনা তাদের শুনিয়েছে।

ক. “যাব আমি তোমার দেশে" কবিতাটি কে লিখেছেন?

গ.

উদ্দীপকে শহুরে দুই বন্ধুর গ্রাম দেখার যে ব্যাকুলতা প্রকাশ পেয়েছে তোমার পাঠ্য পুস্তকের কোন
কবিতায় এমন অভিব্যক্তি প্রকাশ পেয়েছে- ব্যাখ্যা করো ।

উদ্দীপকে শাহেদ তার গ্রামের যে নয়নাভিরাম বর্ণনা করেছেন “যাব আমি তোমার দেশে" কবিতার
আলোকে তার বর্ণনা দাও।

