## 📖 মূল পাঠ (কবিতা)

একটি কাফি
বিষণ দে

[কবি-পরিচিতি : বিষ্ণু দে ১৯০৯ খিষ্টাব্দে কলকাতায় জনুগ্রহণ করেন । সেন্ট পলস কলেজ থেকে ইংরেজি
সাহিত্যে বিএ সম্মান এবং এমএ ডিগ্রি লাভ করেন। কর্মজীবনে তিনি ইংরেজির অধ্যাপক ছিলেন। ১৯২৩
খিষ্টাব্দে প্রকাশিত 'কল্লোল' পত্রিকাকে কেন্দ্র করে যে সাহিত্যিক গোষ্ঠীর উদ্ভব ঘটে, তিনি ছিলেন তার অন্যতম
কবি। অসাধারণ পাগ্ডিত্যের অধিকারী বিষ্ণু দে পুরাণ ও এঁতিহ্যের ব্যবহারে তার কবিতাকে ভিন্ন এক
মাত্রা দান করেন। তার উল্লেখযোগ্য কাব্য : উব্রশী ও আটোমিস, চোরাবালি, সাতভাই চম্পা, তুমি শুধু
পঁচিশে বৈশাখ, স্মাতিসত্তা ভবিষ্যৎ ইত্যাদি। সাহিত্য আকাদেমি ও জ্ঞানপীঠ পুরস্কারসহ অসংখ্য পুরস্কার ও
সম্মাননায় তিনি ভূষিত হন। ৩রা ডিসেম্বর, ১৯৮২ খষ্টাব্দে বিষ্ণু দে মৃত্যুবরণ করেন ॥|

