### 📝 পাঠ-পরিচিতি : বিষ্ণু দে-র “একটি কাফি' কবিতাটি কবির তুমি শুধু পঁচিশে বৈশাখ কাব্য থেকে
সংকলন করা হয়েছে । এটি একটি প্রকৃতিলগ্ন কবিতা । বাংলার নিসর্গ প্রকৃতি, এর মাঠ-ঘাট, মানুষ
অতুলনীয় এবং বিশেষ আবেদনময় | যে জন এই নিসর্ণ-প্রকৃতি থেকে নগরের আহ্বানে সেখানে
স্থায়ী বসতি গড়েন, তাকেও তার এককালের পল্লিপ্রকৃতি বারবার আকর্ষণ করে; ষড়খতু তার মনে
আবেগের রংধনু তোলে। এর শাশ্বত কারণ হলো, মানুষ স্বভাবত তার নিজভূমের প্রতি খণী হয়। কবি
নিজেও তৃষ্ণার্ত চাতক পাখির মতো তীর নিজভূমের পল্লিপ্রকৃতির জন্য অপেক্ষমাণ । কবিতায় নিসর্গ

প্রকৃতির সঙ্গে মানুষের একাত্মতাই উন্মোচিত হয়েছে।
