# ৪৩তম অধ্যায়: আমি কোনো আগন্তুক নই (আহসান হাবীব)

**বাংলা সাহিত্য • নবম-দশম শ্রেণি (NCTB ২০২৬ শিক্ষাক্রম)**
*কবিতা বিভাগ — রচয়িতা: আহসান হাবীব*

---

### ✍️ কবি-পরিচিতি
> কবি-পরিচিতি : আহসান হাবীব ১৯১৭ খিষ্টাব্দের ২রা জানুয়ারি পিরোজপুর জেলার শঙ্করপাশা গ্রামে জন্মগ্রহণ
করেন। তিনি বরিশালের ব্রজমোহন কলেজে আইএ পর্যন্ত অধ্যয়ন করেন। কর্মজীবনে তিনি সাংবাদিকতাকে
পেশা হিসেবে গ্রহণ করেন। গভীর জীবনবোধ ও আশাবাদ তার কবিতাকে বিশিষ্ট ব্যঞ্জনা দান করেছে।
তীর কবিতার ঘ্লিগ্ঘতা পাঠকচিত্তে এক মধুর আবেশ সৃষ্টি করে। তিনি সামাজিক বৈষম্যের বিরুদ্ধে এবং
দিন দুপুরে। রানী খালের সাঁকো তীর কিশোরপাঠ্য উপন্যাস। আহসান হাবীব তীর সাহিত্যকর্মের জন্য
বালা একাডেমি ও একুশে পদক পুরস্কার লাভ করেন। দৈনিক বাংলা পত্রিকার সাহিত্য সম্পাদক থাকাকালে
১৯৮৫ খিষ্টাব্দের ১০ই জুলাই তার জীবনাবসান ঘটে ।

---

