ক. পাখির খ. কদম আলীর
গ. জোনাকির ঘ. জমিলার মা'র
২। কবি বৈঠায় লালে হাত রাখতে বলেছেন কেন?
ক. শপথ নেয়ার জন্য খ. পরশ অনুভব করার জন্য
গ. কবিকে খুঁজে পাবার জন্য ঘ. অস্তিত্ প্রমাণ করার জন্য
নিচের উদ্দীপকটি পড়ে ৩ ও ৪ নং প্রশ্রের উত্তর দাও।

সবাই তার দিকে উৎসুক দৃষ্টিতে তাকিয়ে থাকে । অবশেষে তার স্বজন টম এলে সব সন্দেহের
অবসান ঘটে ।

৩। উদ্দীপকের টমের সঙ্গে 'আমি কোনো আগন্তক নই” কবিতার সাদৃশ্য রয়েছে _
ক. কদম আলীর
খ. জমিলার মার
গ., অবোধ বালকের
ঘ. ভিনদেশি পথিকের

