# ৪৪তম অধ্যায়: বৃষ্টি (ফররুখ আহমদ)

**বাংলা সাহিত্য • নবম-দশম শ্রেণি (NCTB ২০২৬ শিক্ষাক্রম)**
*কবিতা বিভাগ — রচয়িতা: ফররুখ আহমদ*

---

### ✍️ কবি-পরিচিতি
> কবি-পরিচিতি : ফররুখ আহমদ ১৯১৮ খিষ্টাব্দের ১০ই জুন মাগুরা জেলার মাঝআইল গ্রামে জন্যগ্রহণ করেন।
ফররুখ আহমদ কলকাতা রিপন কলেজ থেকে আইএ পাশ করেন এবং কলকাতার স্কটিশ চার্চ কলেজে
দর্শনে অনার্স ও ইংরেজিতে অনার্সের ছাত্র ছিলেন। কিন্তু পরীক্ষা না দিয়েই কর্মজীবনে প্রবেশ করেন।
কর্মজীবনে তিনি নানা পদে নিয়োজিত হন এবং ১৯৪৭ থেকে ১৯৭২ খিষ্টাব্দ পর্যন্ত তিনি ঢাকা বেতারে স্টাফ
রাইটার পদে নিয়োজিত ছিলেন। ইসলামি আদর্শ ও এঁতিহ্য তাকে কাব্যসৃষ্টিতে প্রেরণা জুগিয়েছে। তার
উল্লেখযোগ্য গ্রন্থ : সাত সাগরের মাঝি, সিরাজাম্‌ ম্বনীরা, নৌফেল ও হাতেম, মুহ্তের কবিতা, পাখির
বাসা, হাতেমতায়ী, নতুন লেখা, হরফের ছড়া, ছড়ার আসর ইত্যাদি । সাহিত্যে অবদানের জন্য তিনি বাং
একাডেমি পুরস্কার, আদমজী পুরস্কার, একুশে পদকসহ (মরণোত্তর) অনেক পুরস্কারে ভূষিত হন। ১৯৭৪
খিষ্টাব্দের ১৯শে অক্টোবর তিনি পরলোকগমন করেন |

---

## 📖 মূল পাঠ (কবিতা)

ষট

ফররুখ আহমদ



বৃষ্টি এলো ... বহু প্রতীক্ষিত বৃষ্টি ! _ পদ্মা মেঘনার
দুপাশে আবাদি গ্রামে, বৃষ্টি এলো পুবের হাওয়ায়,
বিদগ্ধ আকাশ, মাঠ ঢেকে গেল কাজল ছায়ায়;
বিদ্যুৎ্-রূপসী পরী মেঘে মেঘে হয়েছে সওয়ার।
দিকদিগন্তের পথে অপরূপ আভা দেখে তার
বর্ষণ-মুখর দিনে অরণ্যের কেয়া শিহরায়,
রৌদ্র-দগ্ধ ধানক্ষেত আজ তার স্পর্শ পেতে চায়,
নদীর ফাটলে বন্যা আনে পূর্ণ প্রাণের জোয়ার ।

রুণ্ন বৃদ্ধ ভিখারির রগ-ওঠা হাতের মতন
রুক্ষ মাঠ আসমান শোনে সেই বর্ষণের সুর,
তৃষিত বনের সাথে জেগে ওঠে তৃষাতপ্ত মন,
যেখানে বিস্মৃত দিন পড়ে আছে নিঃসঙ্গ নির্জন
সেখানে বর্ষার মেঘ জাগে আজ বিষগ্র মেদুর ॥

---

### 📚 শব্দার্থ ও টীকা : বিদ্যুৎ রূপসী পরী - বিদ্যুৎ চমকানোকে লোকজ ধারণা অনুযায়ী সুন্দরী পরীর সঙ্গে
তুলনা করা হয়েছে; যে মেঘে মেঘে ঘুরে বেড়ায়। সওয়ার - আরোহী। রুগ্ন বৃদ্ধ ভিখারির ... তৃষ্াতণপ্ত
মন - দীর্ঘ বর্ষণহীন দিনে মাঠঘাট শুকিয়ে যে রুক্ষ মূর্তি ধারণ করেছে কবি তাকে রু্ন বৃদ্ধ
ভিখারির রগ-ওঠা হাতের সঙ্গে তুলনা করেছেন। এখন বর্ষণের শুরুতে তৃষ্তঠাকাতর মাঠ-ঘাট ও বনে
দেখা দিয়েছে প্রাণের জোয়ার। তৃষাতপ্ত - পিপাসায় কাতর। বিষ্ন মেদুর - বৃষ্টিবিহীন প্রকৃতির
রুক্ষতা বৃষ্টির আগমনে দূরীভূত হয়েছে। প্রকৃতি এখন স্িপ্ধকোমল হয়ে চারদিক করে
তুলেছে প্রাণোচ্ছুল।

---

### 📝 পাঠ-পরিচিতি: “বৃষ্টি' কবিতাটি ফররুখ আহমদের মুহূর্তের কবিতা কাব্য থেকে সংকলিত হয়েছে।
কৃষিপ্রধান বাংলার বনুপ্রতীক্ষিত বৃষ্টি নিয়ে কবিতাটি লিখিত। প্রকৃতিতে বর্ধা আসে প্রাণস্পন্দন নিয়ে ।
আর বৃষ্টিই বর্ষার প্রাণ। এ সময় নদীর দু-ধারে প্লাবন দেখা দেয়, ফলে পলিমাটির গৌরবে ফসল
ভালো হয়। বৃষ্টির সময় আকাশের সর্বত্র মেঘের খেলা দেখা যায়, বর্ধার ফুল চারদিকে মোহিত করে,
রুক্ষ মাটি বৃষ্টিতে প্রাণ জুড়ায়। বৃষ্টির দিনে সংবেদনশীল মানুষও রসসিক্ত হয়ে ওঠে। তার মনে
পড়ে সুখময় অতীত, পুরনো স্মৃতি, আর সে ভালোলাগার আলপনা আঁকে মনে মনে । এ বৃষ্টি কখনো
বিষণও করে মন, একাকী জীবনে বাড়ায় বিরহ । সুতরাং বৃষ্টি শুধু প্রাকৃতিক ঘটনা বা প্রাকৃতিক
পালাবদলের নিয়ামক নয়, এর সঙ্গে ব্যক্তির জীবনও কতটা সম্পৃক্ত তারই কাব্যরূপ কবিতায় ফুটে
উঠেছে।

কর্ম-অনুশীলন

১। বর্ষার খতুতে প্রকৃতি যে নব সাজে সজ্জিত হয়, তার বিবরণ দাও ।

নমুনা প্রন
বহুনির্বাচনি প্রশ্ন
১। কবি বিদ্যুৎকে কার সঙ্গে তুলনা করেছেন?
ক. কন্যার খ. পরী
গ.. আলোর ঘ. বৃষ্টির

২। “রুগ্ণ বৃদ্ধ ভিখারির রগ-ওঠা হাতের মতন
রুক্ষ মাঠ আসমান - এ চিত্রকল্পে কী ফুটে উঠেছে?

ক. বুভুক্ষ মাঠের চিত্র খ. বর্ষায় বাংলার প্রকৃতি
গ.. বৃষ্টিহীন মাঠের রূপ ঘ. প্রকৃতির বৈরিতা

৩। “আজিকার রোদ ঘুমায়ে পড়িছে ঘোলাটে মেঘের আড়ে" - এ বক্তব্যের বিপরীত ভাব
রয়েছে যে বাক্যে-
ক. বর্ষণমুখর দিনে অরণ্যের কেয়া শিহরায়
খ. রৌদ্র-দগ্ধ ধানক্ষেত আজ তার স্পর্শ পেতে চায়
গ.. দু-পাশে আবাদি গ্রামে, বৃষ্টি এলো পুবের হাওয়ায়
ঘ. নদীর ফাটলে বন্যা আনে পূর্ণ প্রাণের জোয়ার



