### ✍️ মূল পাঠ্যবইয়ের সৃজনশীল প্রশ্ন

কেউবা রঙিন কীথায় মেলিয়া বুকের স্বপনখানি,
তারে ভাষা দেয় দীঘল সুতায় মায়াবী আখর টানি ।
আজিকে বাহিরে শুধু ক্রন্দন ছলছল জলধারে
বেণু-বনে বায়ু নীড়ে এলোকেশ, মন যেন চায় কারে।

ক. বৃষ্টি কবিতায় কোন কোন নদীর কথা উল্লেখ রয়েছে?
, রৌদ্র-দগ্ধ ধানক্ষেত আজ বৃষ্টির স্পর্শ পেতে চায় কেন?
গ. উদ্দীপকের শেষ পঙ্ক্তিটির সঙ্গে বৃষ্টি কবিতার মিল কতটুকু তা ব্যাখ্যা করো।
ঘ. “উদ্দীপকটি “বৃষ্টি কবিতার একটা বিশেষ ভাব প্রকাশ করে মাত্র,সমগ্র ভাব নয়”_ তোমার
উত্তরের পক্ষে যুক্তি দাও ।

---

### ❓ পাঠভিত্তিক প্রশ্ন ও উত্তর (Comprehension Q&A)

> ❓ **প্রশ্ন: ফররুখ আহমদের ‘বৃষ্টি’ কবিতায় বৃষ্টির আগমনে প্রকৃতির রূপবদল কীভাবে বর্ণিত হয়েছে?**
> 💡 **উত্তর:** গ্রীষ্মের রুক্ষতা ও তাপদাহ কাটিয়ে বৃষ্টির শীতল ধারায় মাটি প্রাণবন্ত হয়ে ওঠে, চারপাশের শুষ্কতা দূর হয়ে সজীবতার নতুন জোয়ার আসে।

> ❓ **প্রশ্ন: বৃষ্টি মানবমনে কোন অনুভূতির জন্ম দেয়?**
> 💡 **উত্তর:** বৃষ্টি আনে স্বস্তি, উর্বরতার আনন্দ এবং কৃষকের মনে সোনালী ফসলের উজ্জ্বল স্বপ্ন।
