# ৪৫তম অধ্যায়: মে-দিনের কবিতা (সুভাষ মুখোপাধ্যায়)

**বাংলা সাহিত্য • নবম-দশম শ্রেণি (NCTB ২০২৬ শিক্ষাক্রম)**
*কবিতা বিভাগ — রচয়িতা: সুভাষ মুখোপাধ্যায়*

---

### ✍️ কবি-পরিচিতি
> কবি-পরিচিতি : সুভাষ মুখোপাধ্যায় ১৯১৯ খিষ্টাব্দে ভারতের নদীয়ায় জন্মগ্রহণ করেন । তাঁর
মেহনতি মানুষের মুক্তির সংথামকে ধারণ করতেন। কবি সুভাষ মুখোপাধ্যায় একাধিক জাতীয় ও
সোভিয়েত ল্যান্ড নেহরু পুরস্কার । তিনি ২০০৩ খিষ্টাব্দে কলকাতায় মৃত্যুবরণ করেন |

---

## 📖 মূল পাঠ (কবিতা)

মে-দিনের কবিতা
সুভাষ মুখোপাধ্যায়



ধ্বংসের মুখোমুখি আমরা,
চোখে আর স্বপ্নের নেই নীল মদ্য

চিমনির মুখে শোনো সাইরেন-শঙখ,
গান গায় হাতুড়ি ও কাস্তে

তিল তিল মরণেও জীবন অসংখ্য
জীবনকে চায় ভালোবাসতে |

শতাব্দীলাঞ্কিত আর্তের কান্না
প্রতি নিঃশ্বাসে আনে লজ্জা;

এসে গেছে ধ্বংসের বার্তা,
দুর্যোগ পথ হয় হোক দুবেধ্যি
চিনে নেবে যৌবন-আত্মা ।

মে-দিনের কবিতা
---

### 📚 শব্দার্থ ও টীকা

২২৫

যৌবন আত্মা

বঞ্চিতরা সচেতন না হলে শোষণ থেকে তারা মুক্তি পাবে না । তার জন্য তাদের
সংগ্রাম করতে হবে | তাই “ফুল খেলা' অর্থাৎ অসচেতনভাবে চলতি আনন্দে
গা-ভাসিয়ে দেয়াটা শোষিত-বঞ্চিতের জন্য উচিত হবে না। অদ্য- অর্থাৎ
বর্তমানটা ভীষণ কষ্টের ৷ তাই কবি তাদের সচেতন হতে এবং সংগ্রাম
করতে বলেছেন ।

ভেজে ।
বিপদ সংকেত ।

শত অব্দ বা শত বসর।

পীড়িত ।
খবর |

বলিষ্ঠ আত্মা; সাহস আছে এমন তরুণ |

---

### 📝 পাঠ-পরিচিতি: “মে দিনের কবিতা" সুভাষ মুখোপাধ্যায়ের পদাতিক কাব্য থেকে সংকলিত হয়েছে।
বাস্তবতার প্রেক্ষাপটে রোমান্টিকতার পথ পরিহার করে সংগ্রামের পথে এগিয়ে আসার আহ্বান উচ্চারিত
হয়েছে কবিতায় । ফুল খেলা আর বিলাসী জীবন যাপনের দিন আর নেই । এখন সকলকে এগিয়ে আসতে
হবে সংখামের পথে | সে-পথ কঠিন, সে-পথ দুর্গম, বড় বেশি কঠোর । তবু কবি সে-পথেই আহ্বান
জানিয়েছেন তার প্রিয় মানুষকে । শোষক-নিযতিক-অত্যাচারীর হাত থেকে মানুষের মুক্তির জন্য সংগ্রামের
কথা ব্যক্ত হয়েছে এ কবিতায় । শতাব্দীর পর শতাব্দী ধরে যে-নির্মম শোষণ চলেছে, আজ তা প্রতিহত
করার দিন এসেছে । তাই কবি মুক্তির পথে, সংগাামের পথে সকলকে একাত্ম হতে আহ্বান জানিয়েছেন ।

কর্ম অনুশীলন

১। মেদিবসের ইতিহাস ও তাৎপর্য লেখো ।

