### ✍️ মূল পাঠ্যবইয়ের সৃজনশীল প্রশ্ন

তে নি রি ঠে

হে মহাজীবন আর এ কাব্য নয়

এবার কঠিন কঠোর গদ্য আনো

গদ্যের কড়া হাতুড়িকে আজ হানো

কাস্তে" শব্দের অর্থ কী?

প্রিয় ফুল খেলবার দিন নয় অদ্য/ধবংসের মুখোমুখি আমরা» __ দ্বারা কী বোঝানো হয়েছে?
উদ্ধাতাংশের সঙ্গে 'মে-দিনের কবিতার” কোথায় মিল রয়েছে তা ব্যাখ্যা করো।

“এবার কঠিন কঠোর গদ্য আনো"__ উক্তিটি “মে-দিনের কবিতা”র আলোকে ব্যাখ্যা করো ।

---

### ❓ পাঠভিত্তিক প্রশ্ন ও উত্তর (Comprehension Q&A)

> ❓ **প্রশ্ন: সুভাষ মুখোপাধ্যায়ের ‘মে-দিনের কবিতা’য় শ্রমিকের অধিকারের কোন দাবি ধ্বনিত হয়েছে?**
> 💡 **উত্তর:** শ্রমজীবী মানুষের রক্ত ও ঘামে গড়ে ওঠা সভ্যতায় তাদের ন্যায্য অধিকার, সম্মান এবং শোষণমুক্ত সমাজ গড়ার বিপ্লবী আহ্বান।

> ❓ **প্রশ্ন: মে দিবসের ঐতিহাসিক গুরুত্ব কী?**
> 💡 **উত্তর:** বিশ্বের মজুর ও শ্রমিকের ঐক্য এবং অন্যায় শোষণের বিরুদ্ধে সংহতি ও অধিকার প্রতিষ্ঠার প্রতীক।
