# ৪৭তম অধ্যায়: পোস্টার (আবুল হোসেন)

**বাংলা সাহিত্য • নবম-দশম শ্রেণি (NCTB ২০২৬ শিক্ষাক্রম)**
*কবিতা বিভাগ — রচয়িতা: আবুল হোসেন*

---

### ✍️ কবি-পরিচিতি
> কবি-পরিচিতি : আবুল হোসেন ১৫ই আগস্ট, ১৯২২ খিষ্টাব্দে ভারতের পশ্চিমবঙ্গের কৃষ্ণনগরে জন্মগ্হণ করেন ।
তাঁর পৈতৃক বাড়ি খুলনা জেলার দেয়ারা গ্রামে । আবুল হোসেন কলকাতা প্রেসিডেন্সি কলেজ থেকে অর্থনীতি
বিষয়ে বিএ সম্মান ও এমএ ডিগ্রি লাভ করেন। তার কবিতায় দেশের প্রতি গভীর মমতবোধের স্বচ্ছন্দ
কাব্য হচ্ছে : নববসন্ত, বিরস সংলাপ, হাওয়া তোমার কী দুঃসাহস ইত্যাদি । ইকবালের কবিতা, বিভিন্ন
ভাষার কবিতা, অন্য ক্ষেতের ফসল ইত্যাদি তার অনুবাদ কাব্য । আবুল হোসেন বাংলা একাডেমি
পুরস্কার, একুশে পদক, পদাবলী পুরস্কারসহ প্রচুর পুরস্কার ও সম্মাননায় ভূষিত হয়েছেন। ২০১৪ খিষ্টাব্দের
২৯ জুন তিনি ঢাকায় মৃত্যুবরণ করেন |

