### ✍️ মূল পাঠ্যবইয়ের সৃজনশীল প্রশ্ন
যুগ-যুগান্ত সঞ্চিত ব্যথা ঘোষিয়াছে অভিযান!
ফেনাইয়া ওঠে বঞ্চিত বুকে পুঞ্জিত অভিমান,
ইহাদের পথে নিতে হবে সাথে, দিতে হবে অধিকার ।
ক. কারা দিনরাত সৃষ্টির মাঝে নিয়োজিত?


উদ্দীপকে “পোস্টার কবিতার কোন দিক প্রতিফলিত হয়েছে- ব্যাখ্যা করো ।
“উদ্দীপক “পোস্টার” কবিতার মুলভাব পরিপূর্ণভাবে ধারণ করেনি ।” _ মুল্যায়ন করো ।

