### ❓ পাঠভিত্তিক প্রশ্ন ও উত্তর (Comprehension Q&A)

> ❓ **প্রশ্ন: আবুল হোসেনের ‘পোস্টার’ কবিতায় সমাজের কোন দিকটি ব্যঙ্গ করা হয়েছে?**
> 💡 **উত্তর:** দেয়ালে দেয়ালে সাঁটা ফাঁকা স্লোগান, মিথ্যা রাজনৈতিক প্রতিশ্রুতি এবং বাস্তব মানুষের দুঃখ-কষ্টের প্রতি চরম উদাসীনতা।

> ❓ **প্রশ্ন: পোস্টার কীভাবে সময়ের সাক্ষ্য বহন করে?**
> 💡 **উত্তর:** জনগণের আশা-আকাঙ্ক্ষা এবং প্রতারিত হওয়ার নির্মম সত্যকে পোস্টারের মাধ্যমে প্রতীকীভাবে প্রকাশ করা হয়েছে।
