## 📖 মূল পাঠ (কবিতা)

শামসুর রাহমান

[কবি-পরিচিতি : শামসুর রাহমান ১৯২১ খিষ্টাব্দের ২৩শে অক্টোবর ঢাকা শহরে জনুগ্রহণ করেন। তার পৈতৃক নিবাস
১৯৪৭ খিষ্টাব্দে ইন্টারমিডিয়েট পাশ করেন । তিনি ঢাকা বিশ্ববিদ্যালয় থেকে স্নাতক ডিথ্রি লাভ করেন। তার পেশা
ছিল সাংবাদিকতা । তিনি একনিষ্ভাবে কাব্য সাধনায় নিয়োজিত ছিলেন৷ বিশেষ করে মধ্যবিত্ত নাগরিক জীবনের
প্রত্যাশা, হতাশা, বিচ্ছিন্নতা, বৈরাগ্য ও সংগ্রাম তার কবিতায় সার্থকভাবে বিধৃত । তাঁর প্রধান কাব্য : এখম গান
দ্বিতীয় মৃত্যুর আগে, রৌদ্র করোটিতে, বিধ্বস্ত নীলিমা, নিরালোকে দিব্যরথ, বন্দী শিবির থেকে, বাংলাদেশ স্ব দ্যাখ,
বূক তার বাংলাদেশের হৃদয় ইত্যাদি । এছাড়া তার কিছু অনুবাদ-কবিতা ও শিশুতোষ কবিতা রয়েছে। শামসুর
রাহমান তার অনন্যসাধারণ কৰি-কীর্তির জন্য বাংলা একাডেমি পুরস্কার, একুশে পদকসহ অসংখ্য পুরস্কার ও
সম্মাননায় ভূষিত হন। তিনি ১৭ই আগস্ট, ২০০৬ খিষ্টাব্দে মৃত্যুবরণ করেন ||

