# ৫০তম অধ্যায়: অবাক সূর্যোদয় (হাসান হাফিজুর রহমান)

**বাংলা সাহিত্য • নবম-দশম শ্রেণি (NCTB ২০২৬ শিক্ষাক্রম)**
*কবিতা বিভাগ — রচয়িতা: হাসান হাফিজুর রহমান*

