### ❓ পাঠভিত্তিক প্রশ্ন ও উত্তর (Comprehension Q&A)

> ❓ **প্রশ্ন: হাসান হাফিজুর রহমানের ‘অবাক সূর্যোদয়’ কবিতায় কোন চেতনার বিজয় ঘোষিত হয়েছে?**
> 💡 **উত্তর:** রক্তক্ষয়ী যুদ্ধের শেষে অন্ধকারের অবসান ঘটিয়ে বাঙালির মুক্তির রক্তিম সূর্যের উদয় এবং একটি নতুন স্বাধীন দেশের জন্মবার্তা।

> ❓ **প্রশ্ন: সূর্যোদয়কে কেন ‘অবাক’ বলা হয়েছে?**
> 💡 **উত্তর:** এত অত্যাচার ও ধ্বংসস্তূপের মধ্য থেকেও যে একটি জাতি ফিনিক্স পাখির মতো নতুন সূর্য হয়ে জ্বলে উঠতে পারে, তা বিশ্বকে অবাক করে দিয়েছে।
