# ৫২তম অধ্যায়: চুনিয়া আমার আর্কেডিয়া (রফিক আজাদ)

**বাংলা সাহিত্য • নবম-দশম শ্রেণি (NCTB ২০২৬ শিক্ষাক্রম)**
*কবিতা বিভাগ — রচয়িতা: রফিক আজাদ*

---

### ✍️ কবি-পরিচিতি
> কবি-পরিচিতি : রফিক আজাদ ১৪ই ফেব্রুয়ারি, ১৯৪১ খিষ্টাব্দে টাঙ্গাইল জেলার ঘাটাইল থানার গুণীগ্রামে
জন্গ্রহণ করেন। তিনি ১৯৫৯ খিষ্টাব্দে টাঙ্গাইলের ব্রাহ্মণশাসন উচ্চ বিদ্যালয় থেকে প্রবেশিকা এবং নেত্রকোনা
কলেজ থেকে উচ্চ মাধ্যমিক পাশ করেন । ঢাকা বিশ্ববিদ্যালয় থেকে তিনি বাংলা সাহিত্যে স্রাতক
ও স্াতকোত্তর ডিথি লাভ করেন। তিনি একজন বীর মুক্তিযোদ্ধা । কর্মজীবনে তিনি সাংবাদিকতা, অধ্যাপনা ও
সরকারি চাকরিতে নিয়োজিত ছিলেন। প্রেম, দ্রোহ ও প্রকৃতিনির্ভর কবিতার এক তাৎপর্যপূর্ণ জগৎ তিনি সৃষ্টি
অসামান্য অবদানের জন্য তিনি আলাওল পুরস্কার, বাংলা একাডেমি পুরস্কার, একুশে পদকসহ অনেক পুরস্কার
ও সম্মাননায় ভূষিত হন। ১২ই মার্চ, ২০১৬ খ্রিষ্টাব্দে তিনি মৃত্যুবরণ করেন ।

