### 📚 শব্দার্থ ও টীকা : অন্তহিত - মিলিয়ে যাওয়া, হারিয়ে যাওয়া। মারণান্ত্রময় ... দীড়াবে - স্বাধীনতা যুদ্ধে
বাংলাদেশের অন্যান্য সম্প্রদায়ের মতোই মনে প্রাণে ্ষুদ্র-নৃগোষ্ঠী সম্প্রদায়ও সার্বিকভাবে অংশগ্রহণ করেছিল ।
চুনিয়া গ্রামটিও ক্ষুদ্র-নৃগোষ্ঠী অধ্যুষিত এলাকা । তারা মুক্তিযুদ্ধে যেমন অসীম সাহসিকতার স্বাক্ষর রেখেছেন,
মহামানব গৌতমবুদ্ধ মূলত অহিংস নীতিবাদী ছিলেন । এখানে যে সম্প্রদায়ের কথা বলা হয়েছে তারাও বৌদ্ধ-
ধর্মাবলম্বী, এরা গৌতম বুদ্ধের মতোই শান্তিপ্রিয় ও অহিংস মনোভাবের মানুষ এ বোধটিকে বোঝানো হয়েছে।
যোজনব্যাপী - যোজন শব্দের অর্থ 'অনেক' বা বহু। এখানে শব্দটি স্থানবাচনার্থেই ব্যবহৃত হয়েছে।
যোজনব্যাপী হলো অনেকটা স্থানব্যাপী। আতকে _ চমকে, হঠাৎ ভয় পেয়ে। সাহচর্য _ একসঙ্গে মিলেমিশে ।
দীক্ষা _ তন্জ্ঞান লাভ, এক ধরনের শপথ নেয়া। কুরুক্ষেত্র - গ্রাটান ভারতের একটি এঁতিহাসিক স্থান কুরুক্ষেত্র ।
যেখানে কৌরব এবং পান্ডবদের মধ্যে যুদ্ধ সংঘটিত হয়েছিল। কাহিনীটি মহাভারতে বর্ণিত হয়েছে; নৈরাশ্যবাদী -
নিরাশ ব্যক্তি, হতাশ ব্যক্তি, পিদিম - প্রদীপ, বাতি । আর্কেডিয়া_ গ্রিসের একটি জায়গা, যা বহুকাল আগে
থেকে প্রাকৃতিক সৌন্দর্য এবং শান্তি প্রিয়তার জন্য বিখ্যাত ।

আর্কেডিয়া* কাব্য থেকে সংকলিত হয়েছে । এটি একটি প্রতীকী গদ্য কবিতা । “চুনিয়া নামের একটি
গ্রামের প্রতীকের মধ্য দিয়ে কৰি মানুষকে সুন্দরভাবে বাচার আহ্বান জানাচ্ছেন । কবির কথায়, চুনিয়া একটি


চুনিয়া আমার অর্কেডিয়া ২৫১

ছোট্ট আদিবাসী গ্রাম । শহর থেকে অনেক দূরে এর অবস্থান । মনোরম সবুজ প্রকৃতির পটভূমিতে স্থাপিত
বলে চুনিয়া কখনো হিংস্রতা দেখেনি। রক্তপাত দেখেনি । চুনিয়া শুধু জানে মানুষকে ভালোবাসতে ।
মানবসমাজে আজ যে হিংসা হানাহানি রক্তপাত দেখা যায়, চুনিয়াতে এসব নেই। সবাই এখানে তাই
সুখে থাকে । কবি মনে করেন, প্রতিটি মানুষই আসলে এরকম । সভ্যসমাজের অনেকেই এই ধরনের খ্রিঞ্ধ
সুন্দর গ্রামকে অথবা গ্রামের মতো পরিবেশকে বুকের মধ্যে লালন করে থাকেন। চুনিয়া বিশ্বাস করে, মানুষ
মারণাস্ত্র ফেলে, হিংসা-দ্বেষ ভূলে পরস্পর সৎ প্রতিবেশী হবে । কেননা মানবতার পক্ষে দীড়ানোই হচ্ছে
মানবসভ্যতার মূল কথা ।

কর্ম-অনুশীলন
১। চুনিয়া গ্রামের বৈশিষ্ট্যগুলোর একটি তালিকা তৈরি করো ।

নমুনা প্রন

বহুনির্বাচনি প্রশ্ন
