### ✍️ মূল পাঠ্যবইয়ের সৃজনশীল প্রশ্ন
উদ্দীপকটি পড় এবং প্রশ্নগুলোর উত্তর দাও :
জানি নে তোর ধনরতন
আছে কিনা রানির মতন
শুধু জানি আমার অঙ্গ জুড়ায় তোমার ছায়ায় এসে ।
“অন্তর্হিত' শব্দের অর্থ কী?
চুনিয়া এখনো কেন সভ্য সমাজের কারো কারো মনে আছে? বুঝিয়ে লেখো ।
উদ্দীপকটি “চুনিয়া আমার আর্কেডিয়া, কবিতার কোন দিককে প্রতিফলিত করেছে।- ব্যাখ্যা করো ।
উদ্দীপকটি “চুনিয়া আমার আর্কেডিয়া” কবিতার সমগ্র ভাবকে ধারণ করেনি । _ মন্তব্যটি মূল্যায়ন
করো।

