### ❓ পাঠভিত্তিক প্রশ্ন ও উত্তর (Comprehension Q&A)

> ❓ **প্রশ্ন: রফিক আজাদের ‘চুনিয়া আমার আর্কেডিয়া’ কবিতায় ‘চুনিয়া’ কীসের প্রতীক?**
> 💡 **উত্তর:** চুনিয়া হলো কবির স্বপ্নের এক নিষ্কলুষ, শান্তির নীড়—যেখানে হিংসা, হানাহানি ও অস্ত্রের কোনো স্থান নেই; পরম ভালোবাসার এক স্বর্গোদ্যান।

> ❓ **প্রশ্ন: কবি কেন আধুনিক অস্ত্র ও যুদ্ধের বিরুদ্ধে চুনিয়ার নাম উচ্চারণ করেছেন?**
> 💡 **উত্তর:** যুদ্ধবাজ আগ্রাসী শক্তির বিরুদ্ধে ভালোবাসা, মানবিকতা ও শান্তির অমলিন আশ্রয় হিসেবে চুনিয়ার সৌন্দর্যকে তুলে ধরার জন্য।
