### ❓ পাঠভিত্তিক প্রশ্ন ও উত্তর (Comprehension Q&A)

> ❓ **প্রশ্ন: রুদ্র মুহম্মদ শহিদুল্লাহর ‘মিছিল’ কবিতায় তারুণ্যের কোন তেজ ফুটে উঠেছে?**
> 💡 **উত্তর:** অন্যায়ের বিরুদ্ধে কোটি মানুষের গর্জে ওঠা, রাজপথে অধিকার আদায়ের দৃপ্ত পদচারণা এবং শোষকের মসনদ কাঁপিয়ে দেওয়ার বিপ্লবী শক্তি।

> ❓ **প্রশ্ন: মিছিলকে কেন অন্যায়ের বিরুদ্ধে সবচেয়ে বড় হাতিয়ার বলা হয়েছে?**
> 💡 **উত্তর:** মিছিল সাধারণ মেহনতি মানুষের ঐক্য ও সংকল্পের এমন এক মহাসমুদ্র, যা যেকোনো স্বৈরাচার ও অন্যায়কে ভাসিয়ে নিয়ে যাওয়ার ক্ষমতা রাখে।
